INSERT INTO `producciones` (`id_produccion`, `tmdb_id`, `titulo`, `tipo`, `anio`, `sinopsis`, `pais`, `idioma_original`, `portada`, `id_version_origen`) VALUES
(1, 1010581, 'Culpa mía', 'pelicula', '2023', 'Noah debe dejar su ciudad, novio y amigos para mudarse a la mansión de William Leister, el flamante y rico marido de su madre Rafaela. Por otro lado, con 17 años, orgullosa e independiente, Noah se resiste a vivir en una mansión rodeada de lujo. Allí conoce a Nick, su nuevo hermanastro, y el choque de sus fuertes personalidades se hace evidente desde el primer momento.', 'ES', 'es', 'https://image.tmdb.org/t/p/w500/gp31EwMH5D2bftOjscwkgTmoLAB.jpg', NULL),
(2, 1255674, 'Vieja loca', 'pelicula', '2025', 'Pedro recibe un mensaje desesperado de una exnovia pidiéndole que cuide de su senil madre, Alicia. Lo que parece una misión sencilla pronto se convierte en su peor pesadilla. Pedro necesita escapar; pero Alicia no lo deja...', 'AR', 'es', 'https://image.tmdb.org/t/p/w500/a2EdW8sk22fNCvrpOiaHbR2hOuZ.jpg', NULL),
(3, 848334, '¡Caigan las rosas blancas!', 'pelicula', '2025', 'Violeta es una joven directora que, luego de su ópera prima, una road-movie lesbofeminista llamada Las hijas del fuego, ahora intenta hacer un film pornoecológico. Fracasa en ese género tan atractivo como improbable y finalmente se escapa del set junto a sus amigas actrices y amantes de siempre. Vuelven a subirse a la van escolar que habían comprado para la primera película. El viaje sin destino pero con muchas paradas, las conducirá a San Pablo y finalmente a una enigmática isla muy cerca. Allí, Elvira, una extravagante mujer de 70 años lidera una comunidad de vampiras de toda etnia y edad que viven en armonía entre la voluptuosa naturaleza.', 'AR', 'es', 'https://image.tmdb.org/t/p/w500/jwrjFmoLyR8F5jpJt2vUlBb5LpG.jpg', NULL),
(4, 772462, 'No Me Sigas', 'pelicula', '2025', 'Carla sueña con convertirse en una gran influencer, para lograrlo decide fingir un embasa en su apartamento. Sin embargo, al jugar con estas fuerzas oscuras, accidentalmente deja entrar a una entidad maligna real.', 'MX', 'es', 'https://image.tmdb.org/t/p/w500/gop4DwcBeb9T3JTaxwDEHdJNqSq.jpg', NULL),
(5, 1366745, 'Papá x dos', 'pelicula', '2025', 'Santiago decide formar una familia con su novia Ana, a pesar de que ella está embarazada de su ex, Pancho, sin embargo, el verdadero desafío llegará cuando Pancho regrese inesperadamente de Miami para involucrarse en el embarazo, desatando una serie de situaciones cómicas y caóticas en su hogar.', 'AR', 'es', 'https://image.tmdb.org/t/p/w500/yd1FqtFNV7ubC1PvnwN6Qfl0hkB.jpg', NULL),
(6, 1151272, 'Sirat: Trance en el desierto', 'pelicula', '2025', 'Un hombre y su hijo que llegan a una rave perdidos en medio de lo que se describen como las áridas y fantasmagóricas montañas del sur de Marruecos.', 'ES', 'es', 'https://image.tmdb.org/t/p/w500/edEDZwU3kZerqdylZsyCn7feH23.jpg', NULL),
(7, 1244876, 'El molino', 'pelicula', '2024', 'El molino narra la historia de Mayte (Pilar López de Ayala), una ingeniera que regresa a un pequeño pueblo para llevar a cabo un importante proyecto. Su visita coincide con el evento anual del valle. Jaime (Asier Etxeandía) su amor de la infancia, un anciano con Alzheimer, una joven que sueña con salir del valle, una licenciada que trabaja junto a la ingeniera y una mujer que busca el futuro en el pueblo, componen esta historia de personajes cuyas vidas están conectadas por un viejo molino.', 'ES', 'es', 'https://image.tmdb.org/t/p/w500/azfWMAZoTmGIGO55R23a7uuMPRp.jpg', NULL),
(8, 675954, 'El mochaorejas', 'pelicula', '1998', '', 'MX', 'es', 'https://image.tmdb.org/t/p/w500/xRJ6M7k3PKJjTPEoGAbtdrUc47t.jpg', NULL),
(9, 1297953, 'Mi amiga Eva', 'pelicula', '2025', 'Eva acaba de cumplir 50 años. Lleva casada más de 20  y tiene dos hijos adolescentes. Hasta ahora, nada destacable. Pero en un viaje de negocios a Roma, ocurre algo que le da un vuelco a su vida. Conoce a Álex, un guionista que pasa unos días en la ciudad italiana. La atracción instantánea que siente por él, las mariposas en el estómago, la seductora insinuación de una posibilidad... Después de tanto tiempo, recuerda lo que se siente al enamorarse y eso revoluciona su interior. Reaviva una llama que llevaba tiempo extinguida.', 'ES', 'es', 'https://image.tmdb.org/t/p/w500/dolwe6cReEg3zRnIAIPr7C17vqx.jpg', NULL),
(10, 1238188, 'El cautivo', 'pelicula', '2025', 'En 1575, el joven soldado Miguel de Cervantes es capturado en alta mar por corsarios berberiscos y llevado a Argel como rehén. Consciente de que le espera una muerte cruel si su familia no paga pronto su rescate, encuentra refugio en su pasión por contar historias.', 'IT', 'es', 'https://image.tmdb.org/t/p/w500/2vfxMQ3WEA8goCH7LXlAzED9aed.jpg', NULL),
(11, 1156594, 'Culpa nuestra', 'pelicula', '2025', 'La boda de Jenna y Lion propicia el tan deseado reencuentro entre Noah y Nick tiempo después de su ruptura. La incapacidad de Nick para perdonar a Noah se alza como una barrera insalvable. Él, heredero de las empresas de su abuelo y ella, empezando su vida laboral, se resisten a alimentar una llama que aún sigue viva. Pero una vez que sus caminos se han vuelto a cruzar, ¿será el amor más fuerte que el rencor? Secuela de \"Culpa tuya\".', 'ES', 'es', 'https://image.tmdb.org/t/p/w500/6kmi6vmp6iOn4KzI7WfnVtAeJhU.jpg', NULL),
(12, 1589891, 'La hora de los valientes', 'pelicula', '2025', 'Un psicoanalista que cumple servicio comunitario ayuda a un inspector destrozado por una infidelidad. Juntos afrontarán el peligro y descubrirán segundas oportunidades.', 'AR', 'es', 'https://image.tmdb.org/t/p/w500/8ZoDrAbrsSLDVjXsyvOlwjJakUK.jpg', NULL),
(13, 1471345, 'Homo Argentum', 'pelicula', '2025', 'La película consta de 16 mini películas que exploran, con humor y critica social, las características de la identidad argentina.', 'AR', 'es', 'https://image.tmdb.org/t/p/w500/21WlZtv1GZgiD2qAVHOkg63LRmU.jpg', NULL),
(14, 1156593, 'Culpa tuya', 'pelicula', '2024', 'El amor entre Noah y Nick parece inquebrantable, a pesar de las maniobras de sus padres por separarles. Pero el trabajo de él y la entrada de ella en la universidad, abre sus vidas a nuevas relaciones. La aparición de una exnovia que busca venganza y de la madre Nick con intenciones poco claras, removerán los cimientos no solo de su relación, sino de la propia familia Leister. Cuando tantas personas están dispuestas a destruir una relación, ¿puede realmente acabar bien?', 'ES', 'es', 'https://image.tmdb.org/t/p/w500/1jvCVdlgInyItAUEvvvCakm1Yxz.jpg', NULL),
(15, 1252309, 'Pídeme lo que quieras', 'pelicula', '2024', 'Judith Flores es una chica normal. Tiene un trabajo que le apasiona, muy buenos amigos y un padre encantador. Pero su vida cambia radicalmente cuando conoce a Eric Zimmerman, dueño de la empresa donde ella trabaja. Su relación con Eric está a punto de dinamitar su vida por completo.', 'ES', 'es', 'https://image.tmdb.org/t/p/w500/5rtaLwyKAjbceww4J1ro8aA8BNB.jpg', NULL),
(16, 1379963, 'Dímelo bajito', 'pelicula', '2025', 'Kami cree que lo tiene todo controlado… Todo excepto el inesperado regreso de sus vecinos, los hermanos Di Bianco, después de 7 años. Thiago le robó su primer beso y Taylor fue su mejor amigo, pero ahora su vuelta pondrá el mundo de Kami del revés. ¿Podrán superar el pasado que les une? ¿O explotará todo en mil pedazos una vez más?', 'ES', 'es', 'https://image.tmdb.org/t/p/w500/dvebFZgb6HczmYkOA43bGfSrvYl.jpg', NULL),
(17, 1357449, 'Ídolos', 'pelicula', '2026', 'Edu es un joven piloto de motos muy agresivo en quien ningún equipo confía. Eli, jefe del equipo de Aspar Team en Moto2, le ofrece una oportunidad con la condición de que sea su padre, Antonio Belardi, quien le entrene. Edu lleva muchos años sin ver a su padre, un expiloto que se retiró de las pistas tras provocar la muerte de otro piloto durante una carrera. Aunque Edu odia a su padre por haberle abandonado, sabe que solo con él puede llegar a alcanzar su sueño. Edu se someterá al estricto control de preparación que le exige Antonio, el cual incluye dejar a un lado el amor… hasta que conoce a Luna, una joven artista que acaba de abrir un salón de tatuajes justo debajo de su casa.', 'ES', 'es', 'https://image.tmdb.org/t/p/w500/ugwbVoO67N6nZn5A8LTPsn0pkuN.jpg', NULL),
(18, 1578018, 'Bendito corazón', 'pelicula', '2026', '', 'MX', 'es', 'https://image.tmdb.org/t/p/w500/bfburbW7SnLBscRe2hWneN6z9vB.jpg', NULL),
(19, 575769, '4x4', 'pelicula', '2019', 'Buenos Aires, Argentina. Una lujosa furgoneta está aparcada en la acera. Un hombre entra con el propósito de robar lo que encuentre, pero cuando quiere salir, no puede. Las puertas no se abren, el panel de control no responde: la furgoneta se ha convertido en una caja blindada y él está atrapado como un ratón.', 'AR', 'es', 'https://image.tmdb.org/t/p/w500/gMJwGghKysgj6qgcLAWJFhDjFBs.jpg', NULL),
(20, 1370123, 'Aída y vuelta', 'pelicula', '2026', 'Una película de metaficción centrada en el rodaje de un capítulo de la mítica serie de televisión \"Aída\".', 'ES', 'es', 'https://image.tmdb.org/t/p/w500/3k4FKVgaxUZo1CITvj2nFDyNNKy.jpg', NULL),
(21, 1119090, 'Soy Frankelda', 'pelicula', '2025', 'Frankelda, una decidida escritora mexicana del siglo XIX, viaja a su subconsciente para enfrentarse a los monstruos sobre los que ha escrito. Guiada por un príncipe atormentado, deberá restablecer el equilibrio entre ficción y realidad antes de que sea demasiado tarde.', 'MX', 'es', 'https://image.tmdb.org/t/p/w500/bp7TxHXrUlTfCIiA0z2pdkX9X56.jpg', NULL),
(22, 1417, 'El laberinto del fauno', 'pelicula', '2006', 'En la España falangista de 1944, una joven aficionada a los libros e hijastra de un sádico oficial del ejército huye a un misterioso pero cautivador mundo de fantasía.', 'MX', 'es', 'https://image.tmdb.org/t/p/w500/953ZprqPxXSfhHvjBVRiIv7fSP6.jpg', NULL),
(23, 427997, 'El Inca', 'pelicula', '2016', 'Basada en la historia real y personal de un boxeador, Edwin \"El inca\" Valero, dos veces campeón mundial de boxeo, que pasó a ser uno de los máximos símbolos del Chavismo. Acompañado siempre de su esposa, el carismático boxeador de Los Andes venezolanos peleó en rings en todas partes del mundo, propiciando grandes espectáculos y acabando con muchos de sus rivales a través de sus fulminantes nocauts. Sin embargo, a medida que avanzaba profesionalmente, su vida personal comienza a tambalearse. Establece una relación con otra mujer y se hace preso de sus inseguridades y adicción a las drogas. Al punto de llevarlo a su propia destrucción.', 'VE', 'es', 'https://image.tmdb.org/t/p/w500/s9epaAT47IMUFMliCikS7WOmIki.jpg', NULL),
(24, 1304625, 'Campamento Garra de Oso', 'pelicula', '2025', 'Maia, una imaginativa y alborotada niña, y Jan, un niño miedica de ciudad, lucharán a contrarreloj para salvar el campamento de verano amenazado por el excéntrico constructor Sebastián Sebastián. Para ello, buscarán sin descanso un oso que creen que todavía habita en el valle pero que nadie ha visto. En esta intrépida aventura les ayudará Fritz, una divertida y gruñona mofeta… ¡que habla! y que se unirá al equipo para salvar el valle y sus animales.', 'ES', 'es', 'https://image.tmdb.org/t/p/w500/9VZSbOxvHTOy8cDpk5YoXItsgIX.jpg', NULL),
(25, 912032, 'Mar.IA', 'pelicula', '2024', 'Alina es la sonidista de una película erótica. Cuando la protagonista de su film muere en el set, y los productores deciden no llamar a la policía, se desencadenaran una serie de siniestros eventos que pondrán en peligro la vida de todos.', 'AR', 'es', 'https://image.tmdb.org/t/p/w500/bGEEiHbooWHDU8lACzmA9wlHtoW.jpg', NULL),
(26, 501367, 'Mar sangriento (La gaviota roja)', 'pelicula', '1965', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/6lvzHgSOICHAnaI9YBCocr6Kxrc.jpg', NULL),
(27, 30688, 'Géminis', 'pelicula', '2005', 'Meme y Jeremías viven rodeados de un entorno familiar disfuncional. A un padre casi ausente se le opone una estructura matriarcal manejada por una madre tan posesiva como dominadora. La confusión general se incrementa cuando llega al hogar Ezequiel, el hijo mayor residente en Barcelona, para celebrar su matrimonio con Montse. En medio del estrés y del vértigo de los festejos, va creciendo la pasión incontrolable entre los dos hermanos menores...', '??', 'es', 'https://image.tmdb.org/t/p/w500/HPE0E5ig1KvQ3jJZY4XdDAVB5h.jpg', NULL),
(28, 1351046, 'El talento', 'pelicula', '2025', 'En una lujosa fiesta de la alta sociedad, Elsa, una estudiante de violonchelo con mucho talento, celebra el aniversario de su amiga Idoia. Rodeada de glamour y promesas de éxito, su noche da un giro inesperado cuando recibe una llamada de su madre. Lo que su madre le pide pone a Elsa en una encrucijada: tiene la posibilidad de sacrificarse para asegurar su futuro, pero a costa de su propia dignidad. Entre la música, el privilegio y la moral, Elsa deberá decidir quién es y hasta dónde está dispuesta a llegar.', 'ES', 'es', 'https://image.tmdb.org/t/p/w500/UHbbLwjeUASlQR4J7SM6BF7cOZ.jpg', NULL),
(29, 344514, 'Violencia', 'pelicula', '2015', 'Violencia es una película sobre la experiencia vivencial de la violencia en los seres humanos. La película explora esta situación desde la observación cuidadosa de los detalles de la vida cotidiana de tres personas, desde la enrarecida atmósfera de normalidad en el conflicto armado colombiano. (FILMAFFINITY)', '??', 'es', 'https://image.tmdb.org/t/p/w500/e05o5ULMAYYh6zwRkzvI1YWTNc1.jpg', NULL),
(30, 811072, 'Dos', 'pelicula', '2021', 'Un hombre y una mujer se despiertan pegados por el abdomen. David y Sara no se conocen. Ambos están desnudos. Ambos rondan los 35 años. Están en un lugar misterioso que no reconocen. Por el aspecto del lugar, parece una habitación de hotel. Tras el susto inicial, tratan de mantener la calma e intentar pensar porqué están ahí. No recuerdan cómo han llegado hasta la misteriosa habitación, ni qué hicieron las horas antes. David sugiere la posibilidad de que hayan sido drogados y secuestrados. Ambos deben confiar en el otro para desvelar el misterio, pero Sara sospecha de David. Mientras intentan atar cabos, descubren que estar pegados dificulta en extremo hasta las actividades más mundanas (además de hacer que aflore una inevitable atracción mutua a pesar de las circunstancias). Ambos se ven obligados a compartir con un desconocido sus secretos más íntimos y vergonzosos para poder descifrar el misterio.', 'ES', 'es', 'https://image.tmdb.org/t/p/w500/v23nJWsYGaI3ysikMBWJgIjcGwL.jpg', NULL),
(31, 537971, 'Mia', 'pelicula', '2017', 'MIA es un cortometraje erótico-documental autobiográfico que retrata los roles de dominación y sumisión entre dos jóvenes. Aya Wolf, una actriz de 25 años, encarna a la protagonista, que relata sin censura y sin tapujos sus confesiones más íntimas en su primer acercamiento a un mundo totalmente nuevo.', 'ES', 'es', 'https://image.tmdb.org/t/p/w500/nEmw1fZOQp2qFGdrak3ipCbe31G.jpg', NULL),
(32, 73029, 'El regalo', 'pelicula', '2008', 'El Regalo es la historia de 3 amigos entrañables. Francisco, Pacheco y Tito. Francisco, viudo y recién jubilado, está pasando por un momento difícil. Para animarlo sus dos amigos deciden hacerle un regalo. Lo invitan a un paseo a las termas de Chillán y además invitan a Lucy, novia de juventud de Francisco, quién ilusionada acepta acompañarlos. Pero las cosas no siempre resultan como las ideamos. Este paseo les traerá muchas sorpresas, conocerán a Carmen, Nicolás y Martín y cambiará los planes y las vidas de todos.', '??', 'es', 'https://image.tmdb.org/t/p/w500/mVW4U0A7cXBhZcaCDGj6n3g0Bba.jpg', NULL),
(33, 772445, 'Jezabel', 'pelicula', '2022', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/dymrURF0YE84knBKdvgANnuBMjK.jpg', NULL),
(34, 903026, 'Berlanga!!', 'pelicula', '2021', '¿Cómo sigue vigente la mirada del genial cineasta español Luis García Berlanga (1921-2010) en un tiempo cuya cultura popular poco tiene que ver con la suya? Dado que para comprender los secretos de un artista es esencial conocer a la persona que hay detrás, su familia, sus amigos, sus colaboradores, así como prestigiosos cineastas y actores trazan una semblanza colectiva de un creador tan singular como universal.', '??', 'es', 'https://image.tmdb.org/t/p/w500/8UBsC1ux1zJyFmjmf7jEB055rg4.jpg', NULL),
(35, 676839, 'Animales humanos', 'pelicula', '2020', 'La armonía de un vecindario aparentemente idílico se ve trastocada cuando un perro ataca a una niña.', '??', 'es', 'https://image.tmdb.org/t/p/w500/5Ba51RwONmbrotqX1FgHELYtffU.jpg', NULL),
(36, 816741, 'Ojos Grises', 'pelicula', '2018', 'En un futuro postapocalíptico, la humanidad es daltónica. Un científico brillante muere repentinamente, dejando su precioso maletín lleno de una droga sintética altamente adictiva que permite a la gente ...', '??', 'es', 'https://image.tmdb.org/t/p/w500/xAfG881XAEqVCnM4Huu2AlQy8f0.jpg', NULL),
(37, 772220, 'Tremendo Escopetón', 'pelicula', '1995', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/qcvTTKKVwnFSggEfg6BVuX8u6MD.jpg', NULL),
(38, 125441, 'Pulgarcito', 'pelicula', '1957', 'En una cabaña del bosque viven el leñador Matías, su esposa y sus siete hijos: Pablo, Pancho, Pedro, Juan, José, Felipe y el más diminuto de todos, Pulgarcito. Para ayudar a sus padres los niños van a cortar leña al bosque donde los sorprende el malvado ogro de quien tratan de escapar, refugiándose en una casa en la noche, sin saber que ésta es la guarida del ogro.', '??', 'es', 'https://image.tmdb.org/t/p/w500/p2SkPiRlcdqZ4VoR9RgWiYK2h3V.jpg', NULL),
(39, 462183, 'Salvaje Despertar', 'pelicula', '2016', '‘Salvaje despertar’ es una cinta que reflexiona sobre el despertar sexual de dos hermanos, Emma y Toni. El problema surge cuando los protagonistas se enamoran del mismo chico. En la cinta se tratan las principales razones de la homofobia, entre las que se encuentran los miedos, las inseguridades y, en algunos casos, una homosexualidad reprimida.', 'ES', 'es', 'https://image.tmdb.org/t/p/w500/qWkWESVyw1nsX89AXshyRa31Bk6.jpg', NULL),
(40, 238509, 'Pequeñeces', 'pelicula', '1950', 'La condesa de Albornoz es una mujer bella y rica a la que no le importa lo que piensen los demás. Sus amigas la odian por los numerosos escándalos que ha protagonizado; de hecho la condesa tiene amores adúlteros, se aprovecha del apellido de su marido y tiene a su hijo Paquito olvidado en un internado, donde se siente el niño más infeliz del mundo. Pero, pronto, su desenfrenada forma de vivir le pasará factura y, poco a poco, la buena sociedad se apartará de ella. Película basada en la novela del Padre Luis Coloma.', '??', 'es', 'https://image.tmdb.org/t/p/w500/1lzhWwOyRSThNJqxbv4kNMwkKJX.jpg', NULL),
(41, 144349, 'Dinamita Jim', 'pelicula', '1966', 'Durante la Guerra de Secesión, un jugador llamado Jim Farrell al ser confundido con un agente del ejército nordista se verá involucrado en una peligrosa misión consistente en transportar 500.000 dólares en oro por más de 500 millas de territorio sudista (desde Los Álamos hasta territorio kiowa). Su situación se agravará al ser perseguido el cargamento no sólo por el ejército del sur sino también por ser codiciado por un bandido mexicano, Pablo Reyes, y por un pistolero llamado Slate contratado por el avaricioso banquero inicialmente implicado en la operación.', '??', 'es', 'https://image.tmdb.org/t/p/w500/gtnbvocIMEGPrjEjX4U0XhYrF5W.jpg', NULL),
(42, 301901, 'Perro callejero', 'pelicula', '1980', 'Un pequeño queda huérfano por el asesinato de su padre, convirtiéndose en un niño de la calle y olvidando su nombre, sólo responde al mote de “Perro”. Una visión mundana de la vida cotidiana y un reflejo del ambiente callejero muy propio de las grandes ciudades.', '??', 'es', 'https://image.tmdb.org/t/p/w500/8x9b184ZNHQVBXjtA03nvCjopW2.jpg', NULL),
(43, 284057, 'Acteón', 'pelicula', '1967', 'Narra las extrañas relaciones entre un pescador y una chica extranjera. (FILMAFFINITY)', '??', 'es', 'https://image.tmdb.org/t/p/w500/iFsSQZhwNxAD55Vd8hUv8Yfq709.jpg', NULL),
(44, 249418, 'Yambaó', 'pelicula', '1957', '', 'MX', 'es', 'https://image.tmdb.org/t/p/w500/bRyd83m2laPmaA0Kp9Kqz4nVeTQ.jpg', NULL),
(45, 359108, 'Viva', 'pelicula', '2015', 'Jesús, un chico cubano de 18 años, intenta encontrar su verdadera identidad. Sobrevive peinando a señoras del barrio y arreglando pelucas en un cabaret de La Habana. Pero su vida cambia por completo cuando su padre, un famoso boxeador al que daban por muerto, sale de la cárcel y regresa para vivir con él. Desde ese momento, lucharán por volver a ser padre e hijo', '??', 'es', 'https://image.tmdb.org/t/p/w500/9JxpXK2FW2AtRRrcxK7nvROPgiV.jpg', NULL),
(46, 485057, 'Te esperaré', 'pelicula', '2017', 'Un famoso escritor español está creando un nuevo personaje ficticio: un hombre de mundo que ha viajado a lo largo y ancho del planeta y que, por una serie de circunstancias, ha terminado en Argentina. Allí conocerá a un arquitecto que esconde un terrible secreto.', 'AR', 'es', 'https://image.tmdb.org/t/p/w500/1JA4dDyOGNLZbQsqgfnkUzKmUID.jpg', NULL),
(47, 980296, 'Los Frikis', 'pelicula', '2024', 'Gustavo idolatra a su hermano mayor Paco y a sus compañeros de banda punk \'Frikis\'. Cuando llega a los frikis la noticia de un posible indulto de los efectos de la crisis económica, hacen lo ahora impensable: inyectarse deliberadamente el VIH para vivir en un hogar de tratamiento administrado por el gobierno. Es allí donde crean su propia utopía para vivir y tocar música libremente.', 'US', 'es', 'https://image.tmdb.org/t/p/w500/kCGWNd8yFQ3E695kYuaUUv62pJP.jpg', NULL),
(48, 258162, 'Epílogo', 'pelicula', '1984', 'Durante muchos años Rocabruno y Ditirambo firmaban conjuntamente sus novelas, trabajaban juntos y estaban enamorados de la misma mujer, pero llegó un momento en que se separaron. Diez años después, Ditirambo visita a Rocabruno con la intención de que escriban juntos su última novela, \"Epílogo\".', '??', 'es', 'https://image.tmdb.org/t/p/w500/lSUIUEGws9Lkgi8TSp8h4A0SeHX.jpg', NULL),
(49, 573384, 'Prohibido', 'pelicula', '1970', 'Dos jóvenes adultos, hermano y hermana, descubren que ambos fueron adoptados, y comienzan a desarrollar sentimientos adultos hacia el otro. ¿Es esto lo peor, lo más perverso que haya ocurrido? Las opiniones difieren.', '??', 'es', 'https://image.tmdb.org/t/p/w500/7bnqKhLMPAaRbiNQDsTN7p2wHjL.jpg', NULL),
(50, 675722, 'Sábado negro', 'pelicula', '1959', 'Un hombre sale en busca de emociones distintas cuando su esposa e hijos salen de viaje, conoce a una mujer que intenta involucrarlo como autor de un asesinato.', '??', 'es', 'https://image.tmdb.org/t/p/w500/v9tlD5UOW1zz69fiJqFrcY2PDs6.jpg', NULL),
(51, 2470, 'Belle Époque', 'pelicula', '1992', 'Poco antes de estallar la Guerra Civil española (1936-1939), Fernando decide desertar y se refugia en una casa de campo, donde es bien acogido por Manolo, un pintor excéntrico que vive retirado debido a sus ideas políticas. El chico mantiene sucesivamente relaciones con las cuatro hijas de su protector (Rocío, Violeta, Clara y Luz), sin saber muy bien de cuál de ellas está enamorado.', 'FR', 'es', 'https://image.tmdb.org/t/p/w500/Aeiy8R2cTm15WaosWpnFIOxetCJ.jpg', NULL),
(52, 369397, 'Cargamento prohibido', 'pelicula', '1966', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/6tzdt9rlCZl1WvP9A3qn3ku2cUg.jpg', NULL),
(53, 737450, '27 minutos', 'pelicula', '2019', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/yS5xAYlWgT0YAI8s9FIGagVjWlo.jpg', NULL),
(54, 466307, 'Revolución', 'pelicula', '1933', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/ln6RVxENFgbbdqCV9cBgxNj2UHQ.jpg', NULL),
(55, 60901, 'Cupido contrabandista', 'pelicula', '1962', 'Juan es un hombre muy tímido que vive en Ceuta. Todo lo realiza por correspondencia, desde aprender una carrera, hasta encontrar novia. Con el fin de conocer a la mujer de sus sueños, viaja a Madrid, donde también espera demostrar la enorme cantidad de sabiduría que ha amontonado con tanta carta.', '??', 'es', 'https://image.tmdb.org/t/p/w500/nhNDgr5ZWeTZydBcltcwNh4RhKA.jpg', NULL),
(56, 420127, 'Carne apaleada', 'pelicula', '1978', 'Berta ha ido a parar, una vez más, a prisión acusada de estafa. Es carne de cañón e irá pasando por diversas cárceles, sufriendo todo tipo de humillaciones y vejaciones. Adaptación del libro autobiográfico de Inés Palou, una mujer que pasó gran parte de su vida en la cárcel.', '??', 'es', 'https://image.tmdb.org/t/p/w500/sQDxETcR3iZinZIdzBVWDGADjZh.jpg', NULL),
(57, 77429, 'Chechu y familia', 'pelicula', '1992', 'Chechu, un adolescente de 13 años, se queda solo en casa durante unas vacaciones de verano, con la única compañía de unos peculiares familiares y una atractiva doncella a la que pretenderá conquistar.', 'ES', 'es', 'https://image.tmdb.org/t/p/w500/rZBzPx0w6IDE3ST1T7K8uXIZvYf.jpg', NULL),
(58, 568770, 'Poseída', 'pelicula', '2025', 'Un ser oscuro y siniestro entra en el cuerpo de un niño inocente.', 'MX', 'es', 'https://image.tmdb.org/t/p/w500/jrBNsLaIZgtV01WhG2HSiXvVuoF.jpg', NULL),
(59, 43777, 'Azúcar amarga', 'pelicula', '1996', 'Gustavo es un joven comunista de La Habana entusiasta de Castro. Yolanda, una firme disidente que quiere ir a cumplir su sueño de ser bailarina en Miami. El amor les une, pero también les hace tambalearse todas sus convicciones políticas.', 'US', 'es', 'https://image.tmdb.org/t/p/w500/g9h6lcc5DKGepI1OUov94fo3fcV.jpg', NULL),
(60, 675186, 'Radio Patrulla', 'pelicula', '1951', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/vBITiLJTLNOtPqTRtytDTa1ZYNF.jpg', NULL),
(61, 288594, 'Gregorio', 'pelicula', '1985', 'La película cuenta las aventuras de Gregorio, un niño indígena que migra con su familia desde un pequeño pueblo en los Andes a Lima, la capital. Gregorio vive el choque cultural entre el mundo andino y el mundo caótico y violento de la ciudad.', '??', 'es', 'https://image.tmdb.org/t/p/w500/r7lmlVZB1jOLH3ELkal4jhG9w5g.jpg', NULL),
(62, 503865, 'Cantaclaro', 'pelicula', '1946', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/vcxzctyAcGtJnGIsPbvvQgqpTo3.jpg', NULL),
(63, 1493009, 'Cobre', 'pelicula', '2025', '', 'MX', 'es', 'https://image.tmdb.org/t/p/w500/xXuDJUCU8m83OjyqAh79rbHtrAZ.jpg', NULL),
(64, 818647, 'A través de mi ventana', 'pelicula', '2022', 'Raquel lleva toda la vida loca por Ares, su atractivo y misterioso vecino. Lo observa sin ser vista y es que, muy a su pesar, no han intercambiado ni una palabra. Raquel tiene muy claro su objetivo: conseguir que Ares se enamore de ella. Pero ella no es una niña inocente y no está dispuesta a perderlo todo por el camino, y mucho menos a sí misma...', 'ES', 'es', 'https://image.tmdb.org/t/p/w500/3F5MkMadQOWiZNVaNuOuw6UaK7a.jpg', NULL),
(65, 551641, 'Olimpia', 'pelicula', '2018', 'La película cuenta la historia de Raquel, Rodolfo y Hernán, miembros de una brigada de la UNAM durante el movimiento estudiantil en México en 1968. A través de sus fotografías, películas y escritos, conoceremos la historia del día en que el ejército tomó la universidad. y cómo sus estudiantes se unieron, gritaron y nunca olvidaron.', '??', 'es', 'https://image.tmdb.org/t/p/w500/my9vUV1un8XWyDkjgEpLwNS3iS6.jpg', NULL),
(66, 1314786, 'Zeta', 'pelicula', NULL, 'Cinco antiguos espías españoles que, décadas atrás, participaron en una operación secreta en Colombia, son asesinados al mismo tiempo en diferentes partes del mundo.', '??', 'es', 'https://image.tmdb.org/t/p/w500/cy1aXkmjTqCkqzY6EWGUQKX2rXr.jpg', NULL),
(67, 2588, 'Caótica Ana', 'pelicula', '2007', 'Caótica Ana es la historia-viaje de Ana durante cuatro años de su vida, de los 18 a los 22. Una cuenta atrás, 10, 9, 8, 7… hasta el 0, como en la hipnosis, a través de la cual Ana comprueba que no vive sola, que su existencia parece la continuación de otras vidas de mujeres jóvenes que murieron de forma trágica y que habitan en el abismo de su memoria inconsciente. Ese es su caos.', '??', 'es', 'https://image.tmdb.org/t/p/w500/zTHzKN20nDerUMOGBALdRyk7rK2.jpg', NULL),
(68, 623666, 'El cazador', 'pelicula', '2020', 'Ezequiel, un adolescente de 15 años, se queda solo en casa mientras sus padres viajan a Europa. Carga con el peso de desear otros hombres y mantenerlo en secreto. Hasta que conoce a Mono, un hermoso skater, pero esa unión le ofrecerá mucho más que la conexión, la intimidad y el sexo que buscaba. Aterriza en una situación escalofriante que posiblemente lo hará sentir más solo de lo que ya estaba.', '??', 'es', 'https://image.tmdb.org/t/p/w500/6Lc0iKaZSDHRl0rpaNsQM4N2adS.jpg', NULL),
(69, 524149, 'Flor de fango', 'pelicula', '1942', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/8eYGvrjO2IB9hDhXeAz0cBJPhTt.jpg', NULL),
(70, 115903, 'Colegas', 'pelicula', '1982', 'Los hemanos Antonio y Rosario y el novio de ésta, José, deben enfrentarse diariamente a las dificultades derivadas de su humilde condición social. Ninguno tiene trabajo y las escasas oportunidades que se les presentan para lograrlo hacen que se fortalezcan los lazos que les unen.', '??', 'es', 'https://image.tmdb.org/t/p/w500/hAlIzdwCGKCFwr3BOE6S86NzsWi.jpg', NULL),
(71, 483494, 'Oso Polar', 'pelicula', '2017', 'Heriberto da un relevo a una reunión escolar a dos amigos (Flor y Trujillo). En el camino, descubrimos que fueron sus peores matones.', '??', 'es', 'https://image.tmdb.org/t/p/w500/dlWUAjXTi8fkokXHHuEjRxttwA7.jpg', NULL),
(72, 276652, 'Vivir Mata', 'pelicula', '2002', 'En la ciudad más grande del mundo (México, D.F.), Diego y Silvia tienen un encuentro amoroso excepcional basado en el engaño. Durante una larga jornada del día hacia la noche, en un ambiente delirante donde todo parece fuera de control, la pareja descubre que para vivir el verdadero amor, a veces es necesario mentir.', '??', 'es', 'https://image.tmdb.org/t/p/w500/u1CkNfc5PAsCjTwU3IqKxskAyvh.jpg', NULL),
(73, 306838, 'Magallanes', 'pelicula', '2015', 'La vida de un taxista da un giro inesperado, el día que una mujer que conoció hace 25 años en los violentos años en que fue un soldado del Ejército peruano y luchaba contra el grupo terrorista Sendero Luminoso se sube a su vehículo, teniendo un reencuentro inesperado con su pasado oscuro, lo que lo impulsa a realizar un riesgoso plan para tratar de ayudarla a conseguir dinero.', '??', 'es', 'https://image.tmdb.org/t/p/w500/bVzC42W7RLWJIOXxRJPgYDTovKF.jpg', NULL),
(74, 114168, 'Perras', 'pelicula', '2011', 'Nueve alumnas han de permanecer en su salón de clases, esperar a que los policías lleguen y las interroguen, ya que todas son sospechosas de haber cometido una falta imperdonable, mientras tanto se exploraran sentimientos de cada una de las alumnas.', 'MX', 'es', 'https://image.tmdb.org/t/p/w500/jrJrgwFjAyzkZLiaU5dA8o1hcUA.jpg', NULL),
(75, 1118031, 'Apocalipsis Z: el principio del fin', 'pelicula', '2024', 'Cuando una especie de rabia que transforma a la gente en criaturas agresivas se extiende por el planeta, Manel se aísla en casa con su gato, recurriendo a su ingenio para sobrevivir; pero pronto deberán salir a buscar comida, por tierra y por mar, sorteando muchos peligros.', 'ES', 'es', 'https://image.tmdb.org/t/p/w500/jaBToJ1DZcwn5wOsQeLOXFVlBLn.jpg', NULL),
(76, 615468, 'El adúltero', 'pelicula', '1975', 'Después de enterarse de que su marido, un hombre de negocios, tiene una amante, una mujer provoca un accidente que deja a su esposo convaleciente durante unos meses, tiempo que ella aprovecha para tomar el mando de la empresa y hacerle frente a su rival.', '??', 'es', 'https://image.tmdb.org/t/p/w500/7Z2ojgcThgBDUCewFFot6zOjDmT.jpg', NULL),
(77, 1266404, 'Rubio cobrizo', 'pelicula', '2023', 'Raquel y Maika son dos vecinas que llevan 10 años en guerra. La primera tiene diagnosticada una enfermedad mental. La segunda lucha por sobrevivir frente a los fantasmas de su pasado. Ninguna de las dos sabe que empezó antes entre ellas: la guerra o la locura, la represión o la libertad, el sentido común o el delirio. Ambas se relacionan como si fueran esas dos Españas que se resisten a desaparecer.', '??', 'es', 'https://image.tmdb.org/t/p/w500/8XkR9WUurjcbjaauaR8YbhpnA2X.jpg', NULL),
(78, 56948, 'Máncora', 'pelicula', '2009', 'Tras el suicidio de su padre, Santiago (Jason Day), hereda todas sus deudas, así que decide huir. Su destino será Máncora, una isla al norte de Perú. Allí llega inesperadamente su hermanastra Ximena (Pataky), una joven y hermosa fotógrafa, en compañía de su marido (Enrique Murciano). Así empieza una espiral de excesos, drogas, sexo y celos.', '??', 'es', 'https://image.tmdb.org/t/p/w500/vQmLwB3oNAU4CYwEcyd2bKea5O4.jpg', NULL),
(79, 55, 'Amores perros', 'pelicula', '2000', 'Ciudad de México: un fatal accidente automovilístico afecta trágicamente a tres personas. Octavio, un joven adolescente, decide fugarse con Susana, la esposa de su hermano; el Cofí, su perro, se convierte en el medio para conseguir el dinero que necesitan para poder escapar juntos. Al mismo tiempo, Daniel, un hombre de 42 años, deja a su esposa y a sus hijos para irse a vivir con Valeria, una hermosa modelo. El mismo día en que ambos festejan su nueva vida, el destino hace que Valeria sea víctima del trágico accidente.', 'MX', 'es', 'https://image.tmdb.org/t/p/w500/uoObXx53SjSLLtAavMSIe02zizs.jpg', NULL),
(80, 1148713, 'El correo', 'pelicula', '2024', 'Tras aprovechar la oportunidad de unirse a una organización de blanqueo de capitales, un humilde aparcacoches se mete en un mundo de dinero fácil... y en un romance explosivo.', 'BE', 'es', 'https://image.tmdb.org/t/p/w500/flo8jta3TotJZaF3pvjh9Q2C40U.jpg', NULL),
(81, 52322, 'Octubre', 'pelicula', '2010', 'Clemente es un prestamista poco comunicativo. También es la nueva esperanza de Sofía, su vecina soltera, que cada octubre muestra su devoción al culto del Señor de los Milagros. Su relación comienza cuando Clemente descubre una pequeña niña recién nacida, fruto de su relación con una prostituta que ha desaparecido. Mientras Clemente busca a la madre de la pequeña, Sofía se ocupa del bebé y de las tareas del hogar del prestamista. Con la llegada de estos dos nuevos seres a su vida, Clemente tendrá ocasión de cuestionarse acerca de sus relaciones con los demás.', '??', 'es', 'https://image.tmdb.org/t/p/w500/nGyiAANWzk76y60XYOQl0ms08DL.jpg', NULL),
(82, 116888, 'Albures Mexicanos', 'pelicula', '1985', 'Unos artistas carperos son desalojados del lugar que ocupaban para trabajar. Se instalan en un terreno del adinerado y cruel abogado junior, que busca cómo hacer que abandonen su propiedad para construir mil departamentos. Los artistas llaman a una pariente cabaretera para que los seduzca y por ella junior renuncia a construir y se hace cómico y sociode la carpa, con gran alegría de sus padres, que ahí se divierten.', '??', 'es', 'https://image.tmdb.org/t/p/w500/ik6INPdG5wxeR8nRydxMmari2sO.jpg', NULL),
(83, 994128, 'Viejos', 'pelicula', '2023', 'Manuel (Zorion Eguileor) tiene que mudarse a la casa de su hijo Mario (Gustavo Salmerón) y la familia de éste después de que un terrible suceso acabe con la vida de su anciana mujer. Poco a poco, la realidad se impone: algo incomprensible ocurre con Manuel. Las voces que dice escuchar, las presencias con las que dice hablar. Lena (Irene Anula), la mujer de Mario, quiere echarle de la casa: está segura de que algo espantoso puede ocurrir. Solo Naia (Paula Gallego), la hija adolescente, está de su parte, pero incluso ella empieza a dudar a medida que los fenómenos extraños se suceden en torno a su abuelo, cada vez más perturbado. Es el verano más caluroso de la historia, ha empezado una cuenta atrás y ya es demasiado tarde para pararla.', '??', 'es', 'https://image.tmdb.org/t/p/w500/g8ufvT0cxTju4lQuel0ow29NBtm.jpg', NULL),
(84, 650384, 'Amistades inconvenientes', 'pelicula', '2008', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/k7PgojyXzF3xztdKSpePkxghIhi.jpg', NULL),
(85, 408970, 'Indeleble', 'pelicula', '2016', '', '??', 'es', NULL, NULL),
(86, 724062, 'Casiopea', 'pelicula', '2019', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/q9PndqsNpkWMMb7sEFpJ8VwA08a.jpg', NULL),
(87, 414621, 'Vértigo', 'pelicula', '1945', 'Mercedes  se casó cuando era casi una niña y enviudó siendo aún joven y atractiva. A pesar de ello, decide llevar una vida solitaria en su hacienda, sobre todo cuando su hija Gabriela se va a  estudiar al extranjero. Años después, la chica vuelve para presentarle  a Arturo , su futuro marido. El conflicto se desata porque entre Mercedes y Arturo surge una profunda y peligrosa atracción.  Al ver el dolor de su hija,  arrepentida, acelera los preparativos de la boda.', '??', 'es', 'https://image.tmdb.org/t/p/w500/o0RGQhoago8BVKCteObxP5kOhCl.jpg', NULL),
(88, 709702, 'Dame algo', 'pelicula', '1997', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/69DtY0zu3H5H1IY7BoefiCbvljd.jpg', NULL),
(89, 71786, 'Fausto 5.0', 'pelicula', '2001', 'Adaptación del mito de Fausto.  Supuso el debut cinematográfico del grupo teatral \"La fura dels baus\", un prestigioso grupo catalán de vanguardia que se caracteriza por sus insólitas propuestas y sus anticonvencionales atmósferas y estéticas', '??', 'es', 'https://image.tmdb.org/t/p/w500/gxhwlC8hGWltPNCiLQW1blpo9im.jpg', NULL),
(90, 167471, 'Ladies Nice', 'pelicula', '2013', 'La pelicula está protagonizada por tres chicas de la alta sociedad Mexicana, a las que lo único que le preocupa es irse de fiesta y vivir la vida, ya que tienen todas sus necesidades cubiertas gracias al dinero de sus padres.  En la película vemos las desigualdades tan brutales que existen en la sociedad de México, en donde mientras unas familias no tienen nada, otras lo tienen todo y pueden permitirse gastar miles de dólares en fiesta.  Esto es lo que ocurre con las chicas, que creen que son intocables y que nada les puede ocurrir dado que sus padres son ricos. Por desgracia para ellas, pronto se darán cuenta de que ni siquiera todo el dinero que tienen sus padres las pueden salvar de ciertos problemas, que por cierto, se buscan ellas solas con su actitud y su forma de ser.  La película está muy bien, y muestra cómo la sociedad mexicana está dividida, y los ricos viven una vida irreal.', '??', 'es', 'https://image.tmdb.org/t/p/w500/nN2hmc7ZkM1s0YrrdVkd3tqKzgZ.jpg', NULL),
(91, 48453, 'Concursante', 'pelicula', '2007', 'Martín Circo Martín es el afortunado ganador del mayor concurso de la historia de la televisión: un premio valorado en tres millones de Euros. En esta ácida sátira de la sociedad actual, el golpe de suerte de Martín dará un vuelco a su vida convirtiéndola en una auténtica pesadilla. “Un golpe de suerte… puede arruinar tu vida”.', '??', 'es', 'https://image.tmdb.org/t/p/w500/mt9N1Zio4qQHBdyHtnYIuxoH9Q1.jpg', NULL),
(92, 418829, 'Violación', 'pelicula', '1989', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/ZiuEMwz3RDjVMKhuc9JpuCxWJx.jpg', NULL),
(93, 115301, 'Enamorada', 'pelicula', '1946', 'Durante la Revolución Mexicana, un general rebelde y machista se enamora de la independiente hija de un aristócrata del pueblo que ha ocupado. Esta inesperada atracción desafía sus creencias y provoca un conflicto entre su deber y sus sentimientos.', '??', 'es', 'https://image.tmdb.org/t/p/w500/z5sBg8hIvXz1zi6aPsP1Jbyetm4.jpg', NULL),
(94, 916330, '¡Delirio!', 'pelicula', '1944', '', '??', 'es', NULL, NULL),
(95, 35838, 'Tristana', 'pelicula', '1970', 'Don Lope ha acogido a Tristana en su hogar para cumplir una promesa hecha a sus padres. Pero la joven es muy hermosa y se convierte en la obsesión del anciano, que a fuerza de tiempo y de paciencia consigue sus favores. Sin embargo, cuando ella conoce a un joven pintor que la enamora, decide cambiar radicalmente el rumbo de su vida', '??', 'es', 'https://image.tmdb.org/t/p/w500/uziTHMqLARpnSEdi1QtdlX9hR8n.jpg', NULL),
(96, 71118, 'Felicidades', 'pelicula', '2000', 'Es Nochebuena en Argentina. Un escritor famoso que no es feliz y que decide viajar al encuentro de su amada; un médico que quiere ligar con una española, y un odontólogo loco por encontrar el juguete que su hijo quiere de regalo. Una ácida visión sobre la otra cara de la navidad, donde la clase media insiste en sostener una celebración que ya ha perdido su naturaleza. Todos la festejan, pero se centra en los que quedan fuera: los protagonistas, que transitan en un mundo al revés, un mundo en el que irónicamente los justicieros se vuelven delincuentes y los nobles, miserables.', '??', 'es', 'https://image.tmdb.org/t/p/w500/ozRxMgEMNITFS2tGRha3da7pJIW.jpg', NULL),
(97, 403584, 'Café Paraíso', 'pelicula', '2008', 'Gallo y Chuy son dos inmigrantes mexicanos que trabajan en la cocina multirracial del Paradise Café, en Los Ángeles. En medio del incesante barullo de la cocina en hora pico, Gallo ensaya su heroica renuncia, con lo que espera recuperar su juventud, su dignidad y hasta ganar el amor de Susan, una mesera gringa. Pero las cosas no son lo que parecen en el Paradise Café, donde la realidad se torna ficción y la ficción realidad.', '??', 'es', 'https://image.tmdb.org/t/p/w500/xkZxbaJ4nl14hIyOV909C5DhfZy.jpg', NULL),
(98, 64228, 'Violanchelo', 'pelicula', '2008', 'Consuelo lleva casi un año soñando con un hombre que se asemeja mucho a su príncipe azul. Sus amigas están convencidas de que se trata sólo de su imaginación, pero para ella se ha convertido en una auténtica obsesión. Al mismo tiempo, Ricardo también lleva algún tiempo teniendo sueños extraños, en esta ocasión son pesadillas donde una joven mujer intenta asesinarle sin motivo aparente. El destino va a hacer que los dos dejen a un lado el mundo onírico y se encuentren cara a cara en la realidad.', '??', 'es', 'https://image.tmdb.org/t/p/w500/9cxq4xuLxvF1aHdv1Znu3jGOXP7.jpg', NULL),
(99, 274110, 'Ciudad delirio', 'pelicula', '2014', 'Javier, un médico español tímido y reservado, asiste en Cali a un congreso de Medicina. Comparte por azar una noche mágica con Angie, bailarina y coreógrafa, cuyas ilusiones están puestas en la audición para formar parte del espectáculo de salsa más famoso del mundo: “Delirio.” A su vuelta a Madrid, Javier no se encuentra a gusto en el trabajo ni con su pareja y, animado por su mejor amiga, quien trabaja como médico en Cali, decide instalarse allí una temporada y volver a tener contacto con pacientes y ejercer la medicina de atención primaria, muy opuesto a los fríos estudios y estadísticas a los que se ha dedicado en los últimos años.', '??', 'es', 'https://image.tmdb.org/t/p/w500/8NA0PfeVy5WDPBqbOcmD63jrHgB.jpg', NULL),
(100, 45192, 'El profe', 'pelicula', '1971', 'Sócrates (Cantinflas) un abnegado maestro que ha consagrado su vida a la enseñanza, sacrifica la comodidad de la gran ciudad para marchar hacia el pueblo del Romeral, donde son necesarios sus servicios. Allí deberá luchar contra el poderoso cacique local, interesado en formentar la ignorancia de sus habitantes. Sócrates cuenta con el apoyo del sacerdote del pueblo y de Hortensia, una joven que acepta alquilarle una habitación en su casa. Ellos y los niños que rápidamente comienzan a admirar a su maestro, son quienes tendrán que luchar contra las fuerzas del cacique y sus aliados.', '??', 'es', 'https://image.tmdb.org/t/p/w500/AdjL0R0c1rS9tld2dx9l9ptr9wf.jpg', NULL),
(101, 446337, 'Xoxontla', 'pelicula', '1978', 'En el México de los años 40, Félix, un pasante de medicina, abre un consultorio en el pueblo de Xoxontla para elaborar un censo de enfermedades.', '??', 'es', 'https://image.tmdb.org/t/p/w500/m1j8GBH1YgrvWYK2qJaVCTb0xFE.jpg', NULL),
(102, 76378, 'Yesenia', 'pelicula', '1971', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/5ZT9JsSBv6pVRBNlxIn9lhrm9Vq.jpg', NULL),
(103, 865140, 'Chilangolandia', 'pelicula', '2021', 'Chilangolandia – o la amas o la odias... pero no le es indiferente a nadie. Es un lugar donde suceden muchas cosas y se cuentan muchas historias, como la de Ramiro, el taxista. Él está convencido de que su vida cambiará cuando su sobrino “El Chulo” se convierta en la próxima estrella de fútbol al probarse en las fuerzas básicas. Del otro lado de la ciudad, Carmen y Miguel – una mujer que busca desesperadamente mejorar su situación económica en compañía de su marido mandilón – recibirán por equivocación una maleta con 10 millones de pesos. El dueño de la maleta buscará recuperar su dinero mientras que Carmen y su marido deberán pagar sus deudas y gastarse el dinero antes de que los atrapen.', '??', 'es', 'https://image.tmdb.org/t/p/w500/gNObb3Q1P2yO2Z14bs6AXx0cWVy.jpg', NULL),
(104, 182543, 'Berlín Blues', 'pelicula', '1988', 'Lola es una cantante que actúa en un club de moda llamado Berlín Blues, frecuentado por las más diversas tribus de jóvenes postmodernos. Cual una Carmen contemporánea, ama la libertad por encima de todo y teme el amor como un jilguero teme la jaula que le impide volar. Reiner Hössler, el director de una Orquesta de Berlín, que ha vivido únicamente para la música, renunciando a todo lo demás, cambia radicalmente cuando conoce a Lola. Completa el triángulo el joven y brillante pianista David Zimmerman, discípulo de Hössler y enamorado de Mozart, del Rock´n Roll y la feroz vitalidad de Lola', '??', 'es', 'https://image.tmdb.org/t/p/w500/omqU24YPHnhc9vZuGPNiJUVJuk7.jpg', NULL),
(105, 882361, 'Eulalia', 'pelicula', '1987', 'La vida de Eduardo transcurre plácida y ordenadamente. El miedo al mañana no existe. Pero un día, un pequeño suceso tras la pared alterará para siempre su destino.', '??', 'es', NULL, NULL),
(106, 77495, 'Mientras duermes', 'pelicula', '2011', 'César es el portero de un edificio de apartamentos y no cambiaría este trabajo por ningún otro, ya que le permite conocer a fondo los movimientos, los hábitos más íntimos, los puntos débiles y los secretos de todos los inquilinos. Si quisiera podría incluso controlar sus vidas, influir en ellas como si fuera Dios, abrir sus heridas y hurgar en ellas. Y todo sin levantar ninguna sospecha. Porque César guarda un secreto muy peculiar: le gusta hacer daño, mover las piezas necesarias para producir dolor a su alrededor. Y la nueva vecina del 5ºB no deja de sonreír. Entra y sale cada día radiante y feliz, llena de luz. Así que pronto se convertirá en el nuevo objetivo del juego de César. Se trata de un reto personal, de una obsesión.', 'ES', 'es', 'https://image.tmdb.org/t/p/w500/aDi56oSNirZStVwgl8R12nkQrIk.jpg', NULL),
(107, 673871, 'El Contratista', 'pelicula', '2018', 'Los Internationals es una versión latina más seria de los Expendables y el A-Team, que contará con un equipo de todos los personajes de habla hispana que representan diferentes partes de América del Sur y el Caribe. La película será divertida y tendrá mucho corazón, pero también analizará más de cerca la violencia real en nuestra sociedad y su glorificación en los videojuegos; comparar los dos para mostrar el gran contraste y su verdadero impacto en nuestros hijos.', '??', 'es', 'https://image.tmdb.org/t/p/w500/mF94urK8492nQJTPZwW7sHDhfvb.jpg', NULL),
(108, 577495, 'Rincón brujo', 'pelicula', '1949', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/997v9YSsYC4yG374AZ1uB7Hnk4X.jpg', NULL),
(109, 77257, 'Exorcismo', 'pelicula', '1975', 'Una joven aristócrata inglesa cae en una aguda crisis con extraños efectos, inexplicables para la medicina. Paralelamente al curso de su enfermedad una serie de crímenes se van sucediendo sin que la policía pueda resolverlos. La hermana de la enfermera empieza a pensar en un caso de posesión diabólica ante el escepticismo de la familia y psiquiatras. Siguiendo al chófer de la familia, la policía descubre una reunión de adorables de Satán en la cuál la sacerdotisa es la joven enfermera y el chófer confiesa ser el autor de los crímenes. Liberada de la enfermedad de la posesión por un exorcista, conseguirá la paz.', '??', 'es', 'https://image.tmdb.org/t/p/w500/cBk6du3Ba9YxDH026envEb0b7pE.jpg', NULL),
(110, 1209711, 'Camino Contigo', 'pelicula', '2024', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/pb1RHIpIsO2DgOUOLtIDqUU1MhT.jpg', NULL),
(111, 911232, 'Cubagua', 'pelicula', '1987', 'Basada en la novela del escritor venezolano Enrique Bernardo Núñez, el film narra la experiencia del ingeniero Leiziaga al descubrir sus dobles históricos en el marco de la colonización de la isla de Cubagua en Venezuela. De esta manera se entrelazan dos historias: una que transcurre en el siglo XVI y otra en el siglo XX. La primera historia se enfoca en la vida de los colonos españoles que llegaron a Cubagua y la explotación de los pueblos indígenas, para la extracción de perlas; la segunda historia, situada en la década de 1920, narra la expedición arqueológica de Leiziaga, financiada por una multinacional petrolera, en la que visita la isla para estudiar las ruinas del asentamiento español, lo que lo lleva a reflexionar sobre el paso del tiempo y la destrucción causada por la explotación humana, y a través de un juego de espejos, darse cuenta de las relaciones entre el pasado, el presente y el futuro.', '??', 'es', 'https://image.tmdb.org/t/p/w500/nLdBnqDFEZT5Mkvsw6Fy6teC6Lv.jpg', NULL),
(112, 52629, 'El infierno', 'pelicula', '2010', 'En el marco de las fiestas del Bicentenario de independencia, Benjamín García, cómo miles de paisanos, regresa a su pueblo deportado de U.S.A. y encuentra un panorama desolador provocado por la crisis económica y la violencia demencial que azotan el lugar. Sin otra opción, y para salvar a su familia de la miseria, García se involucra en el negocio del narco en el que tiene, por primera vez en su vida, una fulgurante prosperidad, pero también un triste y dramático final. Sátira de cáustico humor negro, sobre el mundo del narco, la crisis económica, la corrupción y la violencia irracional que nos aquejan, EL INFIERNO nos lleva a preguntarnos: ¿Habrá este 2010, algo que celebrar?', 'MX', 'es', 'https://image.tmdb.org/t/p/w500/vry7NyLM6I0fL53H2KxCX4uAz5H.jpg', NULL),
(113, 586521, 'Juanita', 'pelicula', '2018', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/ignXkQPwwjbnENr7ZgTwhfZrFoH.jpg', NULL),
(114, 69357, 'Revolución', 'pelicula', '2010', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/1nnB85qJj68vygVH4GOOm0zSDag.jpg', NULL);
INSERT INTO `producciones` (`id_produccion`, `tmdb_id`, `titulo`, `tipo`, `anio`, `sinopsis`, `pais`, `idioma_original`, `portada`, `id_version_origen`) VALUES
(115, 1244880, 'Invasión', 'pelicula', '2024', 'Invasión cuenta la historia de una irrupción extraterrestre que tiene sometido al planeta Tierra. Dos prisioneros de bandos contrarios encerrados en una celda, tres soldados del ejército español refugiados en una fábrica y un matrimonio de científicos a solas con un extraterrestre preso, deberán aprender a confiar en el enemigo para poder sobrevivir la noche más larga de sus vidas.', '??', 'es', 'https://image.tmdb.org/t/p/w500/poZZC9PNg554tLA4nJWvc3gYIaJ.jpg', NULL),
(116, 568776, 'Polvo', 'pelicula', '2019', 'En búsqueda de fama y fortuna como gran actor de Hollywood el Chato dejó San Ignacio, su idílico y apacible pueblo en medio de la nada. Diez años después, en 1982, un cargamento de cocaína es arrojado desde el aire sobre San Ignacio, el Chato es encomendado por la mafia de Tijuana para recuperar la droga a sabiendas de que si no lo hace todos los habitantes del pueblo estarán en peligro. A su regreso el Chato se confronta con la posibilidad de recuperar su vida, su familia y al hijo que no sabía que tenía.', '??', 'es', 'https://image.tmdb.org/t/p/w500/pH28HqCQx1WW4MRPYSGQjz5Ayaw.jpg', NULL),
(117, 473721, 'Carlota', 'pelicula', '1958', 'Londres, 1900. Han asesinado a Carlota la noche en que Charlie, su esposo, había invitado a cenar a Douglas Hilton, famoso detective de Scotland Yard.', '??', 'es', 'https://image.tmdb.org/t/p/w500/lF5wo5BNUAmJPTWoC2MBg195BNf.jpg', NULL),
(118, 771015, 'Gran Valor', 'pelicula', '1980', 'Abel Amoroso, cadete en una escribanía y responsable de llevar los depósitos al banco, es secuestrado por una banda cuyo líder, Luis Santanelli, posee un increíble parecido físico con el cadete.', '??', 'es', 'https://image.tmdb.org/t/p/w500/yPjt29v8bei75gcenY580NKAZJf.jpg', NULL),
(119, 1426968, 'Ya no quedan junglas', 'pelicula', '2025', 'Theo, conocido como \"el Gentleman\", es un ex soldado estadounidense cuya existencia solitaria y miserable transcurre entre sus recuerdos de un pasado mejor con su difunta esposa y su habitual cita de los jueves con Olga, una prostituta a la que paga por conversar, recordando quién fue una vez y soñando con lo que podría haber sido. Cuando Olga es asesinada, busca una venganza brutal. El rastro de sangre que deja es seguido por Iborra, una inspectora de policía alcohólica, y Herodes, un despiadado asesino a sueldo. El cruce de estos personajes al límite tendrá un abrupto desenlace cuando el presente venga a cobrarse las deudas del pasado.', 'ES', 'es', 'https://image.tmdb.org/t/p/w500/9aCPjtt0mxnMmdvdfCuCGDqxEg8.jpg', NULL),
(120, 142965, 'Furtivos', 'pelicula', '1975', 'Ángel (Ovidi Montllor) es un cazador furtivo que vive en un bosque con su madre (Lola Gaos), una mujer tiránica y violenta. En uno de sus escasos viajes a la ciudad, conoce a Milagros (Alicia Sánchez), una chica que ha huido de un reformatorio y que es la amante de un delincuente llamado El Cuqui. Ángel la protege y la lleva a su casa. La animosidad de la madre hacia Milagros, así como la atracción que Ángel siente hacia ella desembocarán en un drama.', '??', 'es', 'https://image.tmdb.org/t/p/w500/qqkjAu9FJKTGINYLnNnLiosyoI5.jpg', NULL),
(121, 284305, 'Musarañas', 'pelicula', '2014', 'Montse  se vio obligada a cumplir el papel materno y paterno con su hermana menor , al haber muerto su madre en el parto de la pequeña siendo abandonadas por su padre . La extraña enfermedad que padece, agorofobia galopante, la retiene en el interior de su vivienda, agravando la situación. Su hermana ha crecido, es la única que le ayuda a conectar con la realidad. Pero un día todo cambia con la llegada de Carlos, un nuevo vecino.', '??', 'es', 'https://image.tmdb.org/t/p/w500/yiUCX28NUoIjjR0qVI1lRgiKzlW.jpg', NULL),
(122, 550637, 'Mi niño, mi caballo y yo', 'pelicula', '1959', 'Un hombre regresa a su pueblo natal después de treinta años de ausencia, ahora convertido en un famoso charro.', '??', 'es', 'https://image.tmdb.org/t/p/w500/eO3PRKQ1VFH10zF1JJpJxkGCUwc.jpg', NULL),
(123, 277387, 'Sólo química', 'pelicula', '2015', 'Oli se enamora de una rutilante estrella del cine y la televisión, Eric Soto, con el que vivirá un romance maravilloso adentrándose en un mundo de glamour, éxito, fama y dinero. Mientras tanto, su mejor amigo Carlos, psicólogo, la intenta convencer que el amor no existe, que es solamente un efecto químico que nos hace confundir la realidad.', '??', 'es', 'https://image.tmdb.org/t/p/w500/k35xr5o5JYTf9D52e6fA4HFXmav.jpg', NULL),
(124, 256756, 'Purgatorio', 'pelicula', '2014', 'Cuenta la historia de una joven que se ve obligada a cuidar del hijo de su recién llegada vecina. El tiempo pasa y nadie aparece para recogerlo, pero lo que es peor es que la actitud del chaval empieza a ser cada vez más rara, llegando a afirmar que hay otro niño escondido bajo la casa de nuestra protagonista.', '??', 'es', 'https://image.tmdb.org/t/p/w500/o22g7myLjN6ldiHFiQTroqVamEJ.jpg', NULL),
(125, 1020315, 'Medusa', 'pelicula', '2022', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/94FDrZd25vf3A6QaZ6Sbz7GbyXX.jpg', NULL),
(126, 411221, 'Ozzy', 'pelicula', '2016', 'La idílica vida de Ozzy, un simpático y pacífico beagle que se ha criado entre algodones junto a la familia Martin, va a dar un vuelco. Cuando su familia no puede llevarle a un largo viaje lejos de su hogar, le depositan en lo que creen que es el mejor balneario canino, Blue Creek. Pero la perfecta estampa del lugar resulta ser una fachada urdida por su villano propietario, y otro destino bien distinto aguarda a Ozzy: éste irá pronto a parar al verdadero Blue Creek, una cárcel para perros, habitada en su mayoría por duros chuchos callejeros y donde prevalece la ley del más fuerte. Allí dentro Ozzy tendrá que esquivar el peligro, encontrar fuerzas donde no creía tenerlas y aprender a apoyarse en Chester, Fronky y Doc, los nuevos amigos que le acompañarán en esta aventura para intentar regresar sano y salvo.', '??', 'es', 'https://image.tmdb.org/t/p/w500/74GSfa2Bj3pCxRCtWpe1xYJ9vXh.jpg', NULL),
(127, 413103, 'Rondalla', 'pelicula', '1949', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/eb4ovKXjKFuZtXJtvtZr3gfIYAb.jpg', NULL),
(128, 1129932, 'Rabia', 'pelicula', '2023', 'Conmocionado por la muerte de su esposa, Alberto se somete a un autoexilio, arrastrando consigo a su hijo, Alan. Esta nueva atmósfera cambiará su relación y ambos tendrán que aprender a sobrellevar una relación padre-hijo. Originada por el enojo y la culpa, Alan cae en una esquizofrenia que gradualmente lo llevará a creer que su padre es un hombre lobo. Alberto sacrificará su vida para salvar la de su hijo.', '??', 'es', 'https://image.tmdb.org/t/p/w500/1hlH3zqX2Nvs0MaW3VizijrhT5U.jpg', NULL),
(129, 88949, 'Los desesperados', 'pelicula', '1969', 'En plena Guerra de Secesión (1861-1865), John Warner, un noble y valiente cabo confederado, decide desertar al enterarse de que su amante va a dar a luz. Pero cuando llega al pueblo se entera de que ha muerto víctima de una epidemia de cólera. El padre de ella, un rico terrateniente mexicano, que nunca aprobó la relación, le entrega el niño que acaba muriendo de hambre por la falta de auxilio de los vecinos. A partir de entonces, John se convertirá en un violento forajido. (FILMAFFINITY)', '??', 'es', 'https://image.tmdb.org/t/p/w500/1LcxPBrhEXxGsBjbXPs3MHYRK5N.jpg', NULL),
(130, 61979, 'Tres metros sobre el cielo', 'pelicula', '2010', 'En Barcelona, dos jóvenes que pertenecen a mundos opuestos se conocen. Ella, la dulce Babi, es una chica de clase alta que vive en un entorno tan protegido como poco excitante. Él, Hugo, conocido como el duro \"H\", es un chico impulsivo e irresponsable, aficionado a las peleas y a las carreras ilegales de motos. Esta es la crónica de un amor inicialmente imposible que arrastrará a ambos a un frenético viaje iniciático a través del cual descubrirán el amor.', 'ES', 'es', 'https://image.tmdb.org/t/p/w500/nNoMfNPnvEzGADXDkP6eJAP81KB.jpg', NULL),
(131, 344763, 'Rosa blanca', 'pelicula', '1961', 'Un agricultor mexicano (Ignacio López Tarso) y su esposa (Rita Macedo) pierden sus tierras ante petroleros estadounidenses en 1937.', '??', 'es', 'https://image.tmdb.org/t/p/w500/3HiVB27oMVmiVsuDAff8xHLuYpj.jpg', NULL),
(132, 430252, 'Confidencias', 'pelicula', '1982', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/2ntgfL46lQwkFkrtDqjazGIOEcv.jpg', NULL),
(133, 1189927, 'El duelo', 'pelicula', '2023', 'Ernesto, un hombre atrapado en una vida gris y atormentado por la depresión, descubre accidentalmente la traición de su esposa, lo que lo lleva al borde del abismo. Incapaz de encontrar el coraje para quitarse la vida, recurre a una red clandestina de sicarios. Su plan es contratar a un asesino para que ponga fin a su sufrimiento de una vez por todas. Pero su mundo se vuelve al revés cuando conoce a Rita, una hermosa mujer de la que se enamora perdidamente. Lo que iba a ser el fin de su vida se convierte en una gran aventura, una carrera frenética por salvar su vida, la de Rita, y el amor recién descubierto.', '??', 'es', 'https://image.tmdb.org/t/p/w500/nFjcIyURaXrU4WWRN7obbipFQGy.jpg', NULL),
(134, 154629, 'Doña Bárbara', 'pelicula', '1943', 'Después de estudiar leyes en Caracas, Santos Luzardo regresa a Altamira, en la llanura venezolana, para hacerse cargo de su ganado. Son tierras dominadas por doña Bárbara, una mujer que tiene sometidos a los campesinos gracias a una mezcla de astucia, mano dura y brujería. Cuando Bárbara conoce a Santos se enamora de él e intente conquistarlo a toda costa. (FILMAFFINITY)', '??', 'es', 'https://image.tmdb.org/t/p/w500/dys7EksOQd1ej4jWmi503kEmSBP.jpg', NULL),
(135, 225641, 'Manto acuífero', 'pelicula', '2013', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/y71OMFsCapBTFYhfsTkJSGBp1Qw.jpg', NULL),
(136, 185633, 'Raza', 'pelicula', '1942', 'La turbulenta historia de la familia Churruca, un noble linaje de valientes marinos, descendientes de Cosme Damián Churruca, héroe español de la batalla de Trafalgar; desde la guerra hispanoamericana (1898) hasta el final de la guerra civil española (1936-39). (En 1950, se estrenó un nuevo corte de la película con menos profundidad ideológica y diez minutos más breve).', '??', 'es', 'https://image.tmdb.org/t/p/w500/PViYtW1PzkJeNv0Pm7rLdcAFmv.jpg', NULL),
(137, 370739, 'Dos valientes', 'pelicula', '1969', '', '??', 'es', NULL, NULL),
(138, 708464, 'Amaina', 'pelicula', '2010', 'Dos hermanos aguardan junto a su madre agonizante el preciso instante en que la lluvia les dé un respiro. La cosecha ya tuvo su tiempo para madurar y ha empezado a debilitarse. Ellos deberán tomar una decisión: quedarse allí a cuidarla o salir a hacer el trabajo antes que el agua destruya la cosecha.', '??', 'es', 'https://image.tmdb.org/t/p/w500/uA1AR9tVo8UKemwalLS6TykmRS0.jpg', NULL),
(139, 516487, 'Bataclán mexicano', 'pelicula', '1956', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/l9OtEwQwU9H5xEjLUaNmZKkA2VB.jpg', NULL),
(140, 420648, 'El bar', 'pelicula', '2017', 'Son las nueve de la mañana y un heterogéneo grupo de personas desayuna en un bar del centro de Madrid. Uno de ellos tiene prisa y decide marcharse. Pero recibe un disparo en la cabeza nada más salir por la puerta. Nadie puede ir a socorrerlo y tampoco entienden lo que ocurre. Todos quedan atrapados dentro del bar.', 'ES', 'es', 'https://image.tmdb.org/t/p/w500/fTQrMo36JzbxNdXztHIvxoheuZp.jpg', NULL),
(141, 532521, 'Subte: Polska', 'pelicula', '2016', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/uyKK0lgd3XfdlIlBDrlZxgPhuqb.jpg', NULL),
(142, 534125, 'Miriam miente', 'pelicula', '2018', 'El tranquilo mundo de una familia pequeño burguesa comienza a desmoronarse a partir del momento en que Miriam, de 14 años, conoce a su novio de Internet. Mientras sus amigas preparan con entusiasmo la tradicional fiesta de los quince años, Miriam no sabe cómo explicar a su familia que su novio es negro.', 'DO', 'es', 'https://image.tmdb.org/t/p/w500/w2dtcQOAPmxjOcHcuxr6eDIEejA.jpg', NULL),
(143, 1575535, 'Tormento', 'pelicula', '2025', '', 'MX', 'es', 'https://image.tmdb.org/t/p/w500/dfJ9PqicF0cswNDsostHrGVueiq.jpg', NULL),
(144, 1237601, 'Papeles', 'pelicula', '2025', 'Ana Méndez, directora jurídica del bufete número dos del mundo en venta de sociedades offshore, se enfrenta a un acontecimiento catastrófico. Se han filtrado 11,8 millones de documentos; es el mayor hackeo digital de la historia de la humanidad: LOS PANAMA PAPERS. Devastada por los acontecimientos, Ana resulta arruinada y emocionalmente rota. Desde ahí, debe remontar su vida.', 'ES', 'es', 'https://image.tmdb.org/t/p/w500/5MFmmUiRRuVXMaR8Ah3GWimVYXQ.jpg', NULL),
(145, 855095, 'Los justos', 'pelicula', '2024', 'Atilio que comienza una nueva etapa de su vida cuando su hija Mónica toma la difícil decisión de ingresarlo en un geriátrico. Indiferente y deprimido, Atilio se muda sin expectativas. Allí conoce a Beto, un señor ocurrente y buscador, que le facilita la posibilidad de salir clandestinamente. Se escapan juntos del geriátrico para visitar la tumba de su difunta esposa. Durante el silencio de la medianoche son testigos en el cementerio de un operativo encubierto de lavado de dinero. Se trata de un grupo de personas que maniobran en una bóveda dinero escondido en un ataúd. Motivado por la posibilidad de resignificar sus vidas y por el botín, Atilio junto a Beto y a Doña Rosa, una astuta e interesante mujer que también vive en la residencia, comenzarán a involucrarse en la investigación y de esta forma aprovechar la oportunidad de darle un nuevo sentido a sus vidas.', '??', 'es', 'https://image.tmdb.org/t/p/w500/ffhjQteKw15YyacruxTaBgdR6nJ.jpg', NULL),
(146, 28478, 'Gordos', 'pelicula', '2009', 'Comedia dramática sobre los excesos y las carencias de la vida. Los complejos, las fobias, las obsesiones, los traumas, los errores, los miedos, la culpa, los deseos, las ilusiones, los retos, los compromisos, las metas, las relaciones, el amor, el sexo, la salud, la familia... La supervivencia, en el más amplio y orondo sentido de la palabra. \"Gordos\" es una historia coral que gira en torno a una terapia de grupo, de gente con problemas relacionados con la obesidad.', '??', 'es', 'https://image.tmdb.org/t/p/w500/50PWvVJXnuZaOCthrdml01KPao.jpg', NULL),
(147, 412593, 'Zompi', 'pelicula', '2005', 'Alex, un niño de 10 años e hijo único, se enfrenta al trauma del divorcio de sus padres, una nueva casa, vecindario y escuela. Alex sueña con ser un pelotero famoso como su padre, pero la inestabilidad de su nueva vida hace de él un niño inseguro e incapaz de reconocer su talento. La llegada de Zompi, un animal virtual con inteligencia, lo transforma y lo ayuda a superar todos sus miedos.', '??', 'es', NULL, NULL),
(148, 1182861, 'Romería', 'pelicula', '2025', 'Marina viaja a Vigo para conocer a la familia de su padre biológico, que murió de sida, al igual que su madre, cuando ella era muy pequeña. A través de los encuentros con sus tíos, tías y abuelos, Marina intenta reconstruir un relato coherente de su padre y de la historia de amor que vivió con su madre, pero no lo consigue: Todos sienten demasiada vergüenza hacia los conflictos de drogas de la pareja, algo que Marina les recuerda con su presencia.', 'ES', 'es', 'https://image.tmdb.org/t/p/w500/svscmm7MZml1JqBMl62REnbxhjP.jpg', NULL),
(149, 128603, 'El extensionista', 'pelicula', '1991', 'Al llegar a efectuar un reparto de tierras en una pequeña comunidad campesina, un joven agrónomo se da cuenta de la miseria en que viven los campesinos del lugar. Intenta hacer justicia, pero es reprimido por los caciques del pueblo.', '??', 'es', 'https://image.tmdb.org/t/p/w500/zYUgFUR47200cX3bu0my7MEJdtR.jpg', NULL),
(150, 1331344, 'No Voltees', 'pelicula', '2026', 'Cuando dos hermanos regresan a ver a su madre, se enfrentan por una presencia violenta y ominosa que habita el hogar de su infancia: su padre.', '??', 'es', 'https://image.tmdb.org/t/p/w500/g3ZeqO6cNvr6cbfUn2FYZ7wAZ6f.jpg', NULL),
(151, 71114, 'Cleopatra', 'pelicula', '2003', 'Cleo, una maestra jubilada (Norma Aleandro), y Sandra (Natalia Oreiro), una popular actriz de telenovelas, hastiadas de sus rutinarias vidas, se lanzan a la carretera para vivir un fin de semana diferente que cambiará por completo sus destinos. En el trayecto, conocen a Carlos (Leonardo Sbaraglia), un campesino que se sumará a la aventura', '??', 'es', 'https://image.tmdb.org/t/p/w500/tVbasLQsCsA5wK9eOWqeo87IQqQ.jpg', NULL),
(152, 772502, 'Caminero', 'pelicula', '1997', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/vhk9mZIU70ykdtbDqieeYbwaRAR.jpg', NULL),
(153, 73911, 'Bullying', 'pelicula', '2009', 'Jordi es un adolescente que cambia de ciudad junto con su madre para iniciar una nueva vida. Pero el destino le reserva una cruel sorpresa, pues cuando traspasa las puertas de su nuevo instituto, cruza sin saberlo la tenebrosa frontera del mismísimo infierno. Para escapar no tendrá más remedio que, en solitario, buscar desesperadamente la salida.', '??', 'es', 'https://image.tmdb.org/t/p/w500/bVPxzNRHTrwtZjYeLTkWV75bMyj.jpg', NULL),
(154, 1370124, 'Sin cobertura', 'pelicula', '2025', 'Rita es la menor de la familia y está harta de que sus padres y hermanos estén siempre mirando el móvil y no le hagan caso. En un viaje al pueblo de su abuela conoce a una pitonisa que le concede un deseo: que desaparezcan los móviles. A la salida del pueblo una intensa niebla rodea el coche y se quedan sin cobertura. El deseo de Rita se ha hecho realidad, pero no exactamente como ella había imaginado... y es que acaban de viajar en el tiempo y están en plena Edad Media. La familia tendrá que usar su ingenio y buscar la forma de volver al presente mientras tratan de sobrevivir en un pueblo feudal en plena Reconquista.', 'ES', 'es', 'https://image.tmdb.org/t/p/w500/k7QB1I0VJgD8ibYv7slV2YtMCrO.jpg', NULL),
(155, 442128, 'Anacronías', 'pelicula', '2000', '', 'MX', 'es', 'https://image.tmdb.org/t/p/w500/1L8bJGZRznBLx0BlcI2mlY9lMyS.jpg', NULL),
(156, 1103052, 'India Pravile', 'pelicula', '2003', 'Film de humor negro que cuenta la historia de Enrique, un director de cine retirado, desactualizado y desocupado, que decide suicidarse ayudado por su nieto.  Black humor film that tells the story of Enrique, a retired, outdated and unemployed film director, who decides to commit suicide with the help of his grandson.', '??', 'es', 'https://image.tmdb.org/t/p/w500/kpRFd4oWznDiwPCpprVw02dW4GJ.jpg', NULL),
(157, 1257021, 'Revolución', 'pelicula', '2002', 'Cuando trates de hacer una revolución, no llames a un banquero, llama a un poeta. Pero ten por seguro que necesitarás la fuerza.', '??', 'es', 'https://image.tmdb.org/t/p/w500/95NN1u56THnfvG3Df00nCe9wmfN.jpg', NULL),
(158, 568768, 'El club de los idealistas', 'pelicula', '2020', 'Siete amigos universitarios se reúnen en el campo para inaugurar la casa donde alguna vez planearon retirarse juntos tras su jubilación. Aranas fue el único miembro del grupo que se quedó viviendo allí, persiguiendo el sueño de todos de una eventual vida rural, apacible y en comunidad. Aquel grupo de idealistas se enfrenta al espejo que son sus mejores amigos, y aún cuando la adultez parece haberles arrebatado sus sueños este reencuentro podría cambiarles la vida.', '??', 'es', 'https://image.tmdb.org/t/p/w500/pCkNgexaBjovYPDAQVOEN2lzXWS.jpg', NULL),
(159, 363208, 'Las sicodélicas', 'pelicula', '1968', 'Un cuarteto de hermanas peligrosas quienes cobran protección a diferentes personajes llegando a consecuencias temibles si no les pagan.', '??', 'es', 'https://image.tmdb.org/t/p/w500/i3iD8JqptQRiWor7a9pjeoXAmXj.jpg', NULL),
(160, 1288998, '1978', 'pelicula', '2025', 'Durante la final del Mundial, en tiempos de dictadura militar, unos torturadores secuestran a un grupo de jóvenes. Lo que comienza como un interrogatorio inhumano se convierte en un verdadero tormento: han secuestrado a personas equivocadas. Eso no es todo, ya que pertenecen a una secta guiada por una fuerza desconocida y el centro clandestino de detención se convertirá en el mismísimo infierno.', '??', 'es', 'https://image.tmdb.org/t/p/w500/zn7oyy7KTlC01XD3pUn82V9Od0P.jpg', NULL),
(161, 755223, 'Sweet Potatoes', 'pelicula', '2021', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/dHx1M5H4k9uwsGyM1hGzxNDaokj.jpg', NULL),
(162, 421845, 'Miedo', 'pelicula', '1956', 'Un ingeniero, Carlos, se reúne con dos estafadores para atracar la caja fuerte de la compañía de electricidad donde trabaja.', '??', 'es', 'https://image.tmdb.org/t/p/w500/hp4PIXkxuduTvh2XHmxYUSUnFaN.jpg', NULL),
(163, 397259, 'Pasodoble', 'pelicula', '1988', 'Una familia, expulsada de su chabola, ocupa el museo cordobés en el que un día vivió el príncipe que, en su juventud, fue amante de la abuela. Los conservadores y administradores del museo, ayudados por un par de inexpertos policías acosan a los ocupas para obligarlos a salir', '??', 'es', 'https://image.tmdb.org/t/p/w500/raQilbxWJUP4OYJzK0MJprpSZcL.jpg', NULL),
(164, 433185, 'La hija de Stalin', 'pelicula', '2015', 'Una onda de choque comenzó cuando la hija de Stalin, Svetlana Iosifovna Alliluyeva, huyó a Occidente. Durante su infancia, permaneció en el centro del poder y era la hija favorita de su padre. Sin embargo, su vida se vio ensombrecida por la muerte y la violencia. Su madre y su hermano murieron, sus familiares fueron asesinados y su pareja fue exiliada por Stalin. El Telón de Acero fue un obstáculo en su sueño familiar. Este documental muestra por primera vez entrevistas con amigos y familiares, fotografías y documentación exclusivas, así como la última y nunca difundida entrevista con Alliloejeva.', '??', 'es', 'https://image.tmdb.org/t/p/w500/2PKBBo0nzvKtW0wysKYVi7f22Bf.jpg', NULL),
(165, 1020617, 'Palabras urgentes', 'pelicula', '2022', 'Por fiestas patrias, a un estudiante se le asigna la importante tarea de condecorar a un reconocido exalumno. Conflictuado por el hecho de que el homenajeado sea su padre, comenzará a sospechar de las verdaderas intenciones que envuelven este evento patrio.', '??', 'es', 'https://image.tmdb.org/t/p/w500/nqgrL7DD4bmE5VLUglQUJAFrVra.jpg', NULL),
(166, 128171, 'Espaldas mojadas', 'pelicula', '1955', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/hTpEs2nEZi0iPC5UZRfXdtYXCsK.jpg', NULL),
(167, 79359, 'Tuno negro', 'pelicula', '2001', 'Un psicópata asesino se infiltra en la tuna universitaria de Salamanca y elige a sus víctimas a través de Internet. Con la noche y la juerga desmadrada como cómplice, el \"Tuno Negro\" comete sus crímenes con una pauta simple: morirán aquellos que sean los peores estudiantes de cada clase. El último no pasará de curso, ni tendrá la opción de repetir.', '??', 'es', 'https://image.tmdb.org/t/p/w500/1KzEc8xepRdHikb3OnneFiRxfz3.jpg', NULL),
(168, 708675, 'Marea', 'pelicula', '2011', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/vW7P0watl9JzD6c5YScvVTXRcfu.jpg', NULL),
(169, 200427, '5-5-5', 'pelicula', '2013', 'Gabriel, un profesor de filosofía y lógica de la secundaria nocturna, que atraviesa problemas conyugales, y que al conocer a una nueva y joven alumna, quien desaparecerá súbitamente luego de acercarlo a los dibujos proféticos de Benjamín Solari Parravicini; se vera inmerso en intentar comprender el significado de esos dibujos, embarcándose junto a su primo Tony, en una historia de suspenso, intriga y drama.', '??', 'es', 'https://image.tmdb.org/t/p/w500/52npu7BUOBeQuKRTrnorWXeO6CW.jpg', NULL),
(170, 527756, 'Adulterio', 'pelicula', '1945', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/dlWn6QinVvuD3jLW5BRbw2bJDBx.jpg', NULL),
(171, 205768, 'De piel de víbora', 'pelicula', '2002', 'Tras regresar de un viaje, Eugenia, una joven dentista, se halla ante un panorama desolador, pues, aprovechando su ausencia, una banda de ladrones encabezados por un temible individuo apodado \"El Simio\", que calza botas de piel de víbora, ha saqueado su casa. Por desgracia, entre los objetos robados se encuentra un álbum de fotografías personales, lo que en especial motiva a Eugenia a tratar de recuperar sus pertenencias, pues este objeto representa sus recuerdos vivos desde la infancia. (FILMAFFINITY)', '??', 'es', 'https://image.tmdb.org/t/p/w500/iogP7YRPvvbHjlRwiykVm8YOld3.jpg', NULL),
(172, 114860, 'Poniente', 'pelicula', '2002', 'Lucía, una joven maestra que vive en Madrid, regresa a su tierra con su hija Clara tras la muerte de su padre. Allí se reencuentra con el pueblo de su infancia, cambiado por la inmigración. Al mismo tiempo que lucha en contra del racismo hacia los trabajadores ilegales, Lucía se enamora de Curro (José Coronado), quien comparte su misma causa. Lucía y Curro se ven forzados a combatir el racismo, aumentando las tensiones que los obligaran a tomar decisiones que cambiaran el destino de sus vidas.', '??', 'es', 'https://image.tmdb.org/t/p/w500/pXdgYSoS2WsnyPF5WUpJKeSPALU.jpg', NULL),
(173, 1208808, 'Turno nocturno', 'pelicula', '2024', 'En los pasillos oscuros de un hospital, deambula el fantasma de una enfermera conocida como \"La planchada\", famosa por su aspecto impecable. Mientras los pacientes creen que ella está ahí para ayudarlos, las enfermeras y doctores conocen la verdad: deben seguir sus reglas al pie de la letra. \"Que nada se te olvide. No te distraigas. No te relaciones con el personal. No te duermas nunca\". Rebeca, una nueva enfermera en periodo de prueba, no solo debe demostrar su valía ante sus superiores, sino también enfrentarse a esta misteriosa y temida entidad.', 'MX', 'es', 'https://image.tmdb.org/t/p/w500/iSSx9Bys64vlOkvkyKXtp19P7Re.jpg', NULL),
(174, 240628, 'Viento negro', 'pelicula', '1965', 'Durante la construcción de la vía del tren en el desierto de Altar, Sonora, un grupo de trabajadores comandado por Manuel Iglesias sufre las consecuencias del aislamiento y de un viento abrasador. La llegada de un grupo de ingenieros jóvenes, entre ellos el hijo de Manuel, contribuye a aumentar las tensiones.', '??', 'es', 'https://image.tmdb.org/t/p/w500/yGLItK0fTpdEr6XlnMJDBOjVz6R.jpg', NULL),
(175, 699030, 'Mariachi Nights', 'pelicula', '2016', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/pT2At4Z6NXi5SYblVoEnsM2TMdf.jpg', NULL),
(176, 160478, 'Divinas palabras', 'pelicula', '1987', 'La acción de este descarnado retrato de la naturaleza humana, basado en la obra de Valle-Inclán, transcurre en la Galicia de principios del siglo XX. Para huir de la pobreza, la esposa de un sacristán de aldea utiliza a un niño hidrocéfalo como atracción de feria. Eso la llevará a enfrentarse a su cuñada, que tiene el mismo propósito, y a meterse de lleno en un mundo en que residen las más bajas pasiones.', '??', 'es', 'https://image.tmdb.org/t/p/w500/3KkymkaXsFx3IRO5Gc972r3ke4u.jpg', NULL),
(177, 571391, 'Chicuarotes', 'pelicula', '2019', 'Chicuarotes trata acerca de ‘el Cagalera’ y ‘el Moloteco’, dos chicos que buscan desesperadamente salir de la situación y de su pueblo natal. La travesía inicia cuando un amigo de ellos les habla de la posibilidad de comprar una plaza en el sindicato de electricistas, para lo cual idean distintas formas de juntar el dinero y poderse ir junto con Sugehili, la novia de ‘el Cagalera’. Esto los lleva por una aventura juvenil que desemboca en un tornado del mundo criminal.', '??', 'es', 'https://image.tmdb.org/t/p/w500/vN43s4gcqANLuVn5ImuTyb673iz.jpg', NULL),
(178, 63555, 'Año bisiesto', 'pelicula', '2010', 'Laura (Mónica del Carmen), una chica de Oaxaca que ha emigrado a la capital, vive sola en un modesto apartamento, en el que trabaja como colaboradora para una editorial. Al margen de su trabajo, recibe esporádicamente la visita de su hermano menor y mantiene furtivos encuentros sexuales con amantes de una sola noche. Cierto día conoce a Arturo (Gustavo Sánchez Parra), un hombre que despierta en ella irrefrenables deseos masoquistas.', '??', 'es', 'https://image.tmdb.org/t/p/w500/97NnQjz6AZTeU1qfolp9nX2LGjd.jpg', NULL),
(179, 144290, 'Simón Blanco', 'pelicula', '1975', 'El campesino y revolucionario zapatista Simón Blanco sigue en armas aunque Zapata ya ha muerto. Simón acompañado de su lugarteniente Andrés visita en su pueblo a su madre, a su novia Natalia y a sus numerosas comadres. El cacique Onésimo y su hermano el comisario Marcial le ponen emboscadas pero él las elude. Un licenciado capitalino convence a Simón de deponer las armas pues el gobierno hará el reparto ejidal. El comisario posee muchas tierras con prestanombres y se casa con Natalia chantajeando a su padre. Simón se embriaga. Al morir el padre, Marcial encierra a Natalia y el cacique despoja a un compadre de Simón y luego lo manda matar. Natalia huye al lado de Simón y se embaraza. El hijo del cacique reclama a éste su proceder y se vuelve guerrillero. El cacique rapta a un ahijado de Simón para obligar al padre de éste a tender una trampa al guerrillero, que es acribillado en un bautizo, pero los villanos también mueren.', '??', 'es', 'https://image.tmdb.org/t/p/w500/wgmTxzT4yqP1VEiZWTofvDYlpus.jpg', NULL),
(180, 39835, 'Jóvenes', 'pelicula', '2004', 'Jordi (Roger Coma), un joven broker, quiere triunfar en la Bolsa cueste lo que cueste. Cristina (Aina Clotet), sólo quiere divertirse, y en la noche de su cumpleaños combina sin control drogas, alcohol y sexo. Pau (Pau Roca), no tiene ningún plan, y en su fallida búsqueda de emociones fuertes adopta actitudes xenófobas y violentas. Tres jóvenes en una huida a ninguna parte persiguiendo una felicidad que resulta ilusoria. \"Jóvenes\" es una película atrevida y valiente que nos habla de la ambición, de la diversión efímera y de la falta de motivaciones. Tres historias entrecruzadas en las que los personajes manifiestan sus de-seos, sus frustraciones, su visión de la vida y la relación con su entorno.', '??', 'es', 'https://image.tmdb.org/t/p/w500/7piKeQEn5F3MPkqqZ7U4te7UKgX.jpg', NULL),
(181, 21194, 'Casi divas', 'pelicula', '2008', 'Alejandro Mateos, uno de los productores de cine más importantes, comienza un casting de talento para encontrar a la protagonista de su próxima película. Cuatro chicas provenientes de diferentes partes del país harán hasta lo imposible por conseguir un lugar en la cinta, aunque no la tendrán fácil, pues deberán enfrentarse a la novia del productor, una actriz con aires de diva (cualquier parecido con la realidad es a propósito) que hará todo lo que esté en sus manos por quedarse con el papel.', '??', 'es', 'https://image.tmdb.org/t/p/w500/5cmSHd37Sov3dJdVjFwr5eGZ3zm.jpg', NULL),
(182, 721763, 'Fuego sagrado', 'pelicula', '1950', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/zddwIyZ0JOwiUTSNiXdvg4Qo10V.jpg', NULL),
(183, 1298234, 'Ceremonia', 'pelicula', '2025', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/9AiDJaBKWzXFeYZrKwcax9NLbFZ.jpg', NULL),
(184, 360678, 'Voto+Fusil', 'pelicula', '1971', 'El film muestra, en tres etapas con diferentes tonalidades de fotografía, la evolución política de Chile a partir de 1937: la subida al poder de Pedro Aguirre Cerda, el sexenato de González Videla y el triunfo de Salvador Allende. Incluye acontecimientos verdaderos como el asesinato del general Schneider, con intercalación de documentales y recuerdos personales del realizador, además de personajes de ficción. Una película que en su época advirtió al naciente gobierno de S. Allende que el voto si no es apoyado por el fusil será rápidamente destruido por la derecha que desea mantener sus privilegios y economía, entonces la revolución no puede ser por la vía electoral. En ella advierte que no se puede esperar que se mantengan impasible después del anuncio público de que van a perder sus privilegios.', '??', 'es', 'https://image.tmdb.org/t/p/w500/wh8aPUq7NoMbS40ORfVJz8ThMmz.jpg', NULL),
(185, 1270108, 'Lenny', 'pelicula', '2024', 'Lenny Goldman es un torpe y solitario universitario que se deja llevar por la inercia de su entorno. El tiempo ocioso del verano amenaza con agudizar su crisis vocacional.', '??', 'es', 'https://image.tmdb.org/t/p/w500/3DpGqD1fBRUIyYl4YCyLfD1AfNQ.jpg', NULL),
(186, 193199, 'Inercia', 'pelicula', '2013', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/jgPc3FVYic1fRRLDNbVVLSVxnIu.jpg', NULL),
(187, 292109, 'Tempestad', 'pelicula', '2017', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/uU14lGYBtY4FnsorF08JSlzDneU.jpg', NULL),
(188, 240606, 'Santa', 'pelicula', '1943', 'Tras quedar embarazada del militar Marcelino, la joven Santa pierde a su hijo y llega al prostíbulo de doña Elvira. Allí se encuentra a gusto entre las mujeres que le enseñan buenos modales y el pianista ciego Hipólito, su enamorado incondicional. Convertida en amante del torero Jarameño, Santa está a punto de irse con él a España cuando Marcelino vuelve a aparecer en su vida.', '??', 'es', 'https://image.tmdb.org/t/p/w500/xFZIP0kxlO4ZuAbrke04MKgXLjr.jpg', NULL),
(189, 1204389, 'Síncopa', 'pelicula', '2023', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/c4GlXIxL163DC5CSHegbNiYHwEu.jpg', NULL),
(190, 391617, 'Capitán Kóblic', 'pelicula', '2016', 'Colonia Helena, Argentina. El misterioso Tomás Kóblic, antiguo piloto de la Armada, trabaja como fumigador al tiempo que lidia con su oscuro pasado y con las intrigas del corrupto comisario de policía…', '??', 'es', 'https://image.tmdb.org/t/p/w500/rJkaGsuvPb4LZciIudFeZgXmApu.jpg', NULL),
(191, 667018, 'Rebelión de los Godínez', 'pelicula', '2020', 'Omar es un joven que trabaja como una botarga en Frikiplaza en la Ciudad de México. Tras un incidente, se ve obligado a buscar un trabajo formal para apoyar económicamente a su abuelo y entra a Relotech, donde no solo es bueno en su trabajo, también lleva una buena relación con el dueño, la asistente de la Jefa de Operaciones y sus compañeros. Cuando todo parece ir bien, un giro inesperado le obligará a poner a prueba sus virtudes para salvar a sus amigos y a la propia empresa.', '??', 'es', 'https://image.tmdb.org/t/p/w500/lRNdTQtAKZUP3D9N2zx5y8O0f1E.jpg', NULL),
(192, 27410, 'Rojo Sangre', 'pelicula', '2004', 'El veterano actor Pablo Thevenet hace años que dejó de ser un triunfador, ya no le queda ni orgullo y se dedica a buscar trabajo sometiéndose a humillantes castings, realizando pruebas ante directores jóvenes que no lo conocen y veteranos que lo han olvidado. Se indigna cuando ve triunfar en los medios a actores, cantantes y presentadores de pacotilla; tanta injusticia acaba por trastornarlo hasta tal punto que tomará una terrible decisión sirviéndose para ello de sus geniales dotes de transformista', '??', 'es', 'https://image.tmdb.org/t/p/w500/aBfHf6ElYcD1HBUeXRh97DQ9qla.jpg', NULL),
(193, 30026, 'No moriré sola', 'pelicula', '2008', 'Cuatro amigas viajan por una zona de la Plata bastante apartada y en el arcén de una solitaria carretera se encuentran con una joven agonizante a la que le han disparado. Mientras la llevan a la policía del pueblo cercano pueden ver a unos tipos armados que parecen ser algo más que furtivos. Mientras declaran ante el solitario agente, llega un vehículo que no hay duda que es el mismo que han visto y que resulta que el tipo que manda el trío es el jefe de la policía.', '??', 'es', 'https://image.tmdb.org/t/p/w500/hUTZwzqa6wRYWgu6FrHUwZ7YZw2.jpg', NULL),
(194, 456589, 'Hit', 'pelicula', '2008', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/vkMsgkKkSwDJpvZ8j6ihId3itcu.jpg', NULL),
(195, 751605, 'La menor', 'pelicula', '1976', 'La adolescente millonaria Susan acude en compañía de una amiga al festival de Río, sin que su familia lo sepa. Posteriormente se traslada a Madrid, junto con su familia, donde conoce a un atractivo vecino.', '??', 'es', 'https://image.tmdb.org/t/p/w500/A5UwMRwqd0y1ehKA9aO0aWwTXJK.jpg', NULL),
(196, 1435957, 'Catalina', 'pelicula', '2017', '', '??', 'es', NULL, NULL),
(197, 914221, 'Melgarejo', 'pelicula', '1937', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/lVqmTCmwDoFtp6Lg881WUNyDvVl.jpg', NULL),
(198, 1160007, 'Divina Señal', 'pelicula', '2023', 'Checo y Chuma deciden utilizar sus habilidades delictivas para hacer el bien y ayudar a la gente. En el camino, aprenden que la amistad y el amor son algo más que clichés.', '??', 'es', 'https://image.tmdb.org/t/p/w500/6qpYwWq6KxuLTjmLfBVcGtjdz4g.jpg', NULL),
(199, 357026, 'Oscar Desafinado', 'pelicula', '2014', 'En tono de broma, Violeta le dice a su novio Óscar que, si ella muere antes, él deberá esperar al menos 2 años antes de salir con otra mujer y que, si no lo hace, ella volverá de la tumba para vengarse. Poco después, Violeta muere. Y Óscar conoce a Ana.', '??', 'es', 'https://image.tmdb.org/t/p/w500/cza0ARXOJ76nPlv302DApxiqPox.jpg', NULL),
(200, 677574, 'El inconveniente', 'pelicula', '2020', 'A Sara le ofrecen comprar la casa perfecta: espaciosa, muy luminosa y extremadamente barata. Tan solo tiene un pequeño inconveniente: Lola, la octogenaria dueña actual, vivirá en ella hasta que muera. Aun así, Sara cree que es un buen negocio y decide comprar y esperar.', 'ES', 'es', 'https://image.tmdb.org/t/p/w500/1Wpofdybiqlgh2ISsez2rviHHWc.jpg', NULL),
(201, 638960, 'La Nave', 'pelicula', '2022', 'Un locutor de radio tiene que lidiar con el cáncer de su hijo con la ayuda de un entrenador.', '??', 'es', 'https://image.tmdb.org/t/p/w500/7AnUnJ9ozESodZau3g0i35qvn2M.jpg', NULL),
(202, 379220, 'Sin Filtro', 'pelicula', '2016', 'Pía (Paz Bascuñán) es una buena mujer que lleva una vida estresada, llena de problemas personales, profesionales y familiares, hasta que un día recurre a una extraña terapia que le hará decir absolutamente todo lo que piensa, sin tener filtro lidiando con las personas que la rodean diciéndoles a la cara las verdades. (FILMAFFINITY)', '??', 'es', 'https://image.tmdb.org/t/p/w500/cISuCIaPdwjJ8YJhBipdslltKl9.jpg', NULL),
(203, 145204, 'Flor de fango', 'pelicula', '2011', 'Augusto Talanquer, un reconocido investigador bioquímico, abandona a su mujer, su trabajo y la comodidad de su vida para ir tras la pista de marlene, una adolescente de 14 años poseedora de una extraordinaria belleza que irrumpió en su vida de manera inesperada', '??', 'es', 'https://image.tmdb.org/t/p/w500/4P76k2ResETGGcC1BiVPYp2IwUm.jpg', NULL),
(204, 124198, 'Monobloc', 'pelicula', '2005', 'La madrina y Perla son el mundo para \"la nenita\", un mundo delimitado por las cuatro paredes de un monoambiente con una única ventana que da a ningún lado. Sólo alteran el espacio y la monotonía, las sesiones de transfusión de sangre a las que se debe someter Perla y los encuentros sexuales casi anónimos de la nena.', '??', 'es', 'https://image.tmdb.org/t/p/w500/slLjOjuPAExATxNxLc1sGFwprBj.jpg', NULL),
(205, 203946, 'Presagio', 'pelicula', '1975', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/ugUF76wui5UPPNhv9tNwjfMMPgz.jpg', NULL),
(206, 346034, '3 idiotas', 'pelicula', '2017', 'Un conjunto de amigos de siempre van a una aventura salvaje llena de risas, en pos de uno de sus compañeros universitarios más próximos que desaparecieron sin dejar indicio un día ya antes de su gran día de graduación. 5 años tras graduarse de la universidad, Felipe y Beto deciden buscar a Pancho, su amigo perdido hace bastante tiempo y líder incontrovertible de la manada.  Los 3 amigos, todos y cada uno de los estudiantes de ingeniería, pasan por instantes imborrables juntos a lo largo de sus días de escuela salvaje, forjando un vínculo fuerte que prueba capaz de resistir aun los obstáculos más inopinados!', '??', 'es', 'https://image.tmdb.org/t/p/w500/hZB9NvNLcxdmoiAh58ZfG8vdXjf.jpg', NULL),
(207, 873794, 'El radioaficionado', 'pelicula', '2021', 'Tras la muerte de su madre, Nicolás, un joven autista de 30 años, decide volver a su ciudad natal. Quiere cumplir una misión, salir a alta mar en dos días. Allí conoce a Ane, su única amiga de la infancia, y solicita su ayuda. Pero las barreras de Niko a la hora de comunicarse no se lo pondrán fácil. Resulta que no todo el mundo está en la misma onda.', '??', 'es', 'https://image.tmdb.org/t/p/w500/vhh0y9Te5ynh7wlTbuWtqCGQVEP.jpg', NULL),
(208, 645632, 'Venena Bibas', 'pelicula', '2016', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/rPwTsJm8AudWJNx1z9ZvnZVKIpA.jpg', NULL),
(209, 464945, 'Coqueluche', 'pelicula', '1970', 'La actriz Victoria Valder se ve obligada a disolver su compañía de teatro por un asunto de celos. Después se marcha a su casa de Marbella, donde conoció a Juan, cuando era un playboy dedicado al turismo femenino. Juan viaja hasta Marbella para hacer las paces con ella.', '??', 'es', 'https://image.tmdb.org/t/p/w500/quIP3QIcLHQ5UE74pD0gjzT72kq.jpg', NULL),
(210, 542061, 'Mi Verdad', 'pelicula', '2004', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/bMiZfUWR3xhLknZfxg4k51F8Eu4.jpg', NULL),
(211, 7276, 'Nordeste', 'pelicula', '2005', 'Después de haberlo sacrificado casi todo para alcanzar el éxito profesional, Hélène (Carole Bouquet), una madura y bella francesa, decide cambiar radicalmente de vida. Su deseo de ser madre la lleva hasta Argentina en busca de un niño al que adoptar. Allí descubre Nordeste, una región salvaje cuya asombrosa belleza contrasta violentamente con la miseria de sus habitantes. (FILMAFFINITY)', '??', 'es', 'https://image.tmdb.org/t/p/w500/lK8W7ILxlifrGAvLPnP9JZTMnKL.jpg', NULL),
(212, 169319, 'Volverás', 'pelicula', '2002', 'Ignacio (Unax Ugalde), un estudiante de arquitectuara con una vida estable, hace más de seis años que no ve a su problemático hermano mayor, Carlos (Tristán Ulloa). Cuando ambos se reencuentran, Ignacio se entera que Carlos tiene problemas con el juego, así que decide intentar ayudarle, aun poniendo su vida en peligro, antes de marcharse con una beca que ha conseguido para irse a estudiar a Los Ángeles.', '??', 'es', 'https://image.tmdb.org/t/p/w500/uA5LXOLB4IkeIs7dA1eCZvOvOUG.jpg', NULL),
(213, 515344, 'La bañera', 'pelicula', '1991', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/gEChyn3Ni97783KHklkBfEGp38y.jpg', NULL),
(214, 254026, 'Rapiña', 'pelicula', '1975', 'Dos humildes leñadores indígenas descubren los restos de un avión que se ha estrellado en lo alto de la sierra y deciden robar las pertenencias de todos los ocupantes muertos en el accidente. Cuando se disponen a hacerlo, llegan dos carboneros con las mismas intenciones. Lo que seguirá en esta historia será un duelo de avaricia y traición, del que nadie saldrá impune', '??', 'es', 'https://image.tmdb.org/t/p/w500/fVAvN8KHCHLfO3hbnmY4yZEjZBf.jpg', NULL),
(215, 832389, 'Herederos', 'pelicula', '2021', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/m1TCj1gZ5OCHWp8JaksBfW2SHZP.jpg', NULL),
(216, 536945, 'Héroes', 'pelicula', '2018', 'La historia de cinco dedos participando en un combate de pulso', '??', 'es', 'https://image.tmdb.org/t/p/w500/s69ytyNN9TeXUV1eXDT2jqvQAZR.jpg', NULL),
(217, 635031, 'Guadalupe Reyes', 'pelicula', '2019', 'Dos amigos de toda la vida deciden intentar el desafío Guadalupe Reyes, que consiste en beber todos los días desde el 12 de diciembre (Día de Nuestra Señora de Guadalupe) hasta el 6 de enero (Día de la Epifanía, la Fiesta de los Tres Reyes).', '??', 'es', 'https://image.tmdb.org/t/p/w500/yTzUT341y6ZxN8Ftu76WJ0R4iGY.jpg', NULL),
(218, 886912, 'Contando ovejas', 'pelicula', '2022', 'Ernesto es un joven solitario, menospreciado por la gente de su entorno. Aun así, la vida de Ernesto dará un giro cuando sus compañeros de piso le ayudan a recuperar la autoestima y confianza en sí mismo que tanto necesita. Para conseguirla, sus amigos tratarán de cumplir todos sus sueños sin medir las consecuencias de los actos, algo que hará que la vida de Ernesto cambie para siempre.', '??', 'es', 'https://image.tmdb.org/t/p/w500/tJ1BmUzBlk4PFcj7jTpRQoWjqGd.jpg', NULL),
(219, 186755, 'Territorio comanche', 'pelicula', '1997', 'Guerra de Bosnia, principios de los noventa. Cuando estalla la contienda, son muchos los corresponsales de guerra que acuden al lugar del conflicto. Pero también estalla la lucha entre los medios de comunicación, que no dudan en explotar el dolor ajeno con tal de subir la audiencia. Laura, una joven periodista de éxito, se instala en Sarajevo durante el asedio al que se vio sometida la ciudad. Allí conoce a Mikel, un experto reportero de firmes principios, y a José, su cámara. El contacto con las víctimas, los encuentros con periodistas de otros países, las disputas con Mikel y José, que desaprueban el enfoque oportunista que ella da a la información, llevan a Laura a reflexionar seriamente sobre su trabajo. Mientras tanto, con colegas de todas las nacionalidades y con la intérprete croata Jadranka, Laura recorre cada día la zona más peligrosa de Sarajevo: lo que ellos llaman \"territorio comanche\".', '??', 'es', 'https://image.tmdb.org/t/p/w500/tQK9bx1EICIik2Up49ZCyUX4BM3.jpg', NULL),
(220, 1005854, 'El Sacrificio', 'pelicula', '2022', '', 'PA', 'es', 'https://image.tmdb.org/t/p/w500/46qQMj3h1B2C2ictVxMCkb0EK2p.jpg', NULL),
(221, 564861, 'Cuatro desertores', 'pelicula', '1970', 'Tres mercenarios abandonan su misión de transportar medio millón de dólares a Casablanca y se dirigen a España, donde conocen a tres chicas de club.', 'ES', 'es', 'https://image.tmdb.org/t/p/w500/7HGa5RImPcaUTWw4Gh1xVepzaqF.jpg', NULL),
(222, 777626, 'Hamelín', 'pelicula', '1969', 'Un guitarrista vagabundo logra con su música que todos los niños vayan tras él.', '??', 'es', 'https://image.tmdb.org/t/p/w500/xVeNsn2Nc4X50WJQpR1hVpiS9l9.jpg', NULL),
(223, 120295, 'Flor silvestre', 'pelicula', '1943', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/8lIiPASdgZe1L2HQkcETmYLLAFn.jpg', NULL),
(224, 387805, '7:19', 'pelicula', '2016', 'Martín y Fernando se encuentran en la recepción del edificio donde trabajan. De pronto, un terremoto los sepulta debajo de siete pisos de concreto y metal retorcido. Son las 7:19 am del 19 de septiembre de 1985. Martín y Fernando son de universos distintos, el destino los obliga a afrontar la muerte juntos; ahora, más que nunca, tendrán que derribar las fronteras que los separan.', '??', 'es', 'https://image.tmdb.org/t/p/w500/8QxTx4IouJQ6uZSYZYpAWG3DVAy.jpg', NULL),
(225, 524276, 'Madrid-Moscú', 'pelicula', '2007', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/AeF5vB9puYYUw7R8ETUo6m59DqI.jpg', NULL),
(226, 240339, 'Rosauro Castro', 'pelicula', '1950', 'La muerte de Cardoza, candidato a presidente municipal de un pueblo y enemigo del cacique Rosauro Castro, lleva al licenciado García Mata a emprender una investigación. Al llegar se da cuenta de que el pueblo entero, incluyendo al presidente municipal, vive atemorizado por el cacique y que solo la venganza logrará poner fin a las injusticias cometidas por Rosauro Castro', '??', 'es', 'https://image.tmdb.org/t/p/w500/ayk7EzEnCCyB7kmK4mM1yrqGUVC.jpg', NULL),
(227, 98962, 'Sor Citroen', 'pelicula', '1967', 'Madrid, España. Cuando una comunidad religiosa que regenta un orfanato compra un coche, la vivaracha e intrépida hermana Tomasa acepta la tarea de ponerse al volante.', '??', 'es', 'https://image.tmdb.org/t/p/w500/onCW28gMja6xGCJLwzbqJtxSUXH.jpg', NULL),
(228, 114247, 'Las melancólicas', 'pelicula', '1971', 'Una mujer es puesta bajo el cuidado de un doctor tras del fallecimiento de su madre que había sido sometida a un exorcismo.', '??', 'es', 'https://image.tmdb.org/t/p/w500/sVjVBNkLKW4hUwrl3y3emBy3zPh.jpg', NULL),
(229, 895868, 'Biónica', 'pelicula', '2025', 'Emma, una joven cuadripléjica, contrata los servicios de la Clínica Biónica, institución presidida por el Dr. Wuntz que por primera vez está autorizada por el estado para realizar un tratamiento que consiste en matar a Emma, separar la cabeza y llevarla a un cuarto de reposo donde la cabeza tomará consciencia mientras dure el tratamiento, y llevar el cuerpo a un quirófano donde a través de implantes se procederá a la recuperación total del mismo y a la instalación de talentos especiales que Emma compró. Pero el Dr. Wuntz quiere ir un paso más lejos y arriesga todo el proceso.', '??', 'es', 'https://image.tmdb.org/t/p/w500/byQJb7SyIaLsoMUCdBbnANAPLfI.jpg', NULL),
(230, 87125, 'Ceremonia sangrienta', 'pelicula', '1973', 'La historia del Marqués Karl Ziemmer y su esposa, Erszebeth Bathory, descendiente de la condesa que solía bañarse en sangre de vírgenes. En la comarca se inicia una serie de crímenes cuyas víctimas son siempre jovencitas cuya sangre es misteriosamente drenada.', 'IT', 'es', 'https://image.tmdb.org/t/p/w500/odhc1ja9p70Na3CMoIw6uL8PNOI.jpg', NULL),
(231, 1045256, 'Los impresentables', 'pelicula', NULL, 'Un adolescente recién expulsado de la Escuela Naval a principios de los años 70 en Argentina se hace amigo de cuatro notorios jóvenes en una pequeña ciudad cercana a Buenos Aires, participa de sus travesuras y aspiraciones, y en el proceso experimenta el primer amor.', '??', 'es', 'https://image.tmdb.org/t/p/w500/taXUd5rqLlsKI4pkZtAvxGrU80v.jpg', NULL),
(232, 416147, 'Prótesis', 'pelicula', '2019', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/zYMtnOkAsZxK2ZHqOh1uIfp0JAb.jpg', NULL),
(233, 1266675, 'Una ballena', 'pelicula', '2025', 'Ingrid, una sicaria con una habilidad especial para infiltrarse y desaparecer sin dejar rastro que proviene de otro mundo, recibe el encargo de Melville para eliminar a un poderoso hombre de negocios que ha llegado a la ciudad y quiere hacerse con el control del puerto.', 'IT', 'es', 'https://image.tmdb.org/t/p/w500/qwf9zfHVdpDRHqerMwZ2NtXItDY.jpg', NULL),
(234, 220620, 'Ismael', 'pelicula', '2013', 'Ismael Tchou, un niño mulato de 8 años, se fuga en el AVE rumbo a Barcelona para conocer a su padre. Su única pista es la dirección de un apartamento, escrita en el remite de una carta dirigida a su madre. Cuando encuentra el edificio, en el apartamento sólo está Nora, una elegante mujer de unos 50 años.', '??', 'es', 'https://image.tmdb.org/t/p/w500/rSBDObfZLedaoxpJy8LYuCroD6F.jpg', NULL),
(235, 412624, 'Remolino', 'pelicula', '1961', 'La joven manipula a los tres hombres de la hacienda, planeando casarse con el padre y jugar con uno o ambos jóvenes.', '??', 'es', 'https://image.tmdb.org/t/p/w500/sC6jwZ5JBsCXnkMwGxW0V8b5ez.jpg', NULL),
(236, 148885, 'Café Mambo', 'pelicula', '2000', '', 'US', 'es', 'https://image.tmdb.org/t/p/w500/dSldW60RTAFinLJuZqwndsoQ3Jw.jpg', NULL);
INSERT INTO `producciones` (`id_produccion`, `tmdb_id`, `titulo`, `tipo`, `anio`, `sinopsis`, `pais`, `idioma_original`, `portada`, `id_version_origen`) VALUES
(237, 1396882, 'Paz', 'pelicula', '1949', 'Ha finalizado la guerra y en pocas horas el país será controlado por los vencedores. Raúl Storni, un civil que ha sabido sacar provecho de la situación comprando divisas en bancos extranjeros, es alcanzado por las últimas bombas del conflicto, perdiendo completamente la memoria. Sin embargo, mientras los tanques entran en la ciudad rescata a una niña y conoce a Elena, una compatriota que le lleva al hospital. Allí se convierte en un nuevo hombre \"Juan Vencido\", y su única ambición es la de cruzar la frontera y casarse con la muchacha que acaba de conocer.', '??', 'es', 'https://image.tmdb.org/t/p/w500/zZNYw4L8kYuU851cbmFY8c1Iv4J.jpg', NULL),
(238, 262492, 'Betibú', 'pelicula', '2014', 'Un popular periódico le encarga a una famosa novelista noir investigar la misteriosa muerte de un poderoso empresario considerado como sospechoso en la extraña muerte de su esposa. A pesar de haber sido absuelto del crimen en un juicio muy publicitado, sigue siendo sospechoso a los ojos de la opinión pública. ¿Están relacionadas las muertes? Instalada en el barrio del empresario fallecido y al escribir la historia del año, la inquisitiva escritora se percata de que el asesinato quizá sea uno entre muchos otros vinculados al oscuro pasado de hombres poderosos.', '??', 'es', 'https://image.tmdb.org/t/p/w500/zN6y7JKRHUBTtva3hyeesMiYH4P.jpg', NULL),
(239, 301001, 'Emiliano Zapata', 'pelicula', '1970', 'Emiliano Zapata era un campesino que entendía los ideales de la clase trabajadora. Se convirtió en una figura decorativa del levantamiento revolucionario en México.', '??', 'es', 'https://image.tmdb.org/t/p/w500/5yitCtk6uOX0W33l7ef1MuFRqdQ.jpg', NULL),
(240, 632142, 'Pequeña Babilonia', 'pelicula', '2014', 'Documental sobre la historia del rock platense, que incluye bandas de diferentes estilos y épocas, como Patricio Rey y Sus Redonditos de Ricota, Virus, Peligrosos Gorriones, Casanovas, Las Canoplas o Estelares.', '??', 'es', 'https://image.tmdb.org/t/p/w500/of3SSwBIXqLtEeq4RZhVcrC2bid.jpg', NULL),
(241, 452707, 'Embrujo antillano', 'pelicula', '1946', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/lJxAPlexZfhy7SyEYKHmKtpVyyx.jpg', NULL),
(242, 766804, 'Girasoles silvestres', 'pelicula', '2022', 'Julia, una joven de 22 años y madre de dos niños, se enamora de Óscar, un chico conflictivo con el que comienza una relación. A medida que pasan tiempo juntos, Julia empezará a plantearse si Óscar es la persona que realmente necesita a su lado, lo que la llevará a iniciar un viaje personal en busca de su felicidad y la de su familia.', '??', 'es', 'https://image.tmdb.org/t/p/w500/tHK4c0UZKrqkmXZ2HJeGNhNetRz.jpg', NULL),
(243, 80713, 'Solas', 'pelicula', '1999', 'María (Ana Fernández) malvive en un oscuro apartamento de un barrio miserable, trabaja eventualmente como chica de la limpieza y, casi con cuarenta años, descubre que está embarazada de un hombre que no la ama. Su soledad es tan grande que sólo encuentra consuelo en la bebida. Su madre (María Galiana), que ha consumido su vida al lado de un hombre violento e intolerante, no tiene ni siquiera el consuelo de tenerla cerca. Con motivo del ingreso de su marido en un hospital, la madre visita a María en su apartamento y conoce a un vecino viudo (Carlos Álvarez) que vive con su perro. La relación que se establece entre estos tres náufragos alivia sus soledades y deja una puerta abierta a la esperanza.', '??', 'es', 'https://image.tmdb.org/t/p/w500/1ovtyHHDjyCXtf46w2Yv3yPeUDY.jpg', NULL),
(244, 834898, 'Polvo somos', 'pelicula', '2020', 'Ane regresa a su pueblo natal al inesperado funeral de su abuelo. La vuelta trae consigo el tenso reencuentro con las mujeres de su familia. Todo adquiere extraños visos cuando empieza a sospechar de ciertas anomalías por parte de la funeraria.', '??', 'es', 'https://image.tmdb.org/t/p/w500/zWGHF13oimNocEIHB21c8yXJGax.jpg', NULL),
(245, 361257, 'El destierro', 'pelicula', '2015', 'Durante la Guerra Civil Española, Teo está destinado a un fuerte pequeño de vigilancia , que se encuentra en un frío e inhóspito lugar en las montañas. Allí conoce a Silverio, su nuevo compañero, con el que tendrá que convivir durante seis largos meses. Las diferentes personalidades de estos dos hombres provocarán muchas tensiones, acentuadas por el espacio limitado. La coexistencia frágil se rompe con la llegada de Zoska, una joven extranjera a quien Silverio encuentra moribunda cerca del refugio. Su presencia en aquel abrupto paraje sembrará la semilla de un conflicto aún más devastador que la propia guerra, capaz de poner en peligro su supervivencia por algo tan humano y primigenio como es el sexo y la amistad.', '??', 'es', 'https://image.tmdb.org/t/p/w500/Akul8Z6Q80X7VHQlEexjS60bscy.jpg', NULL),
(246, 366270, 'Ahí vienen los Mendoza', 'pelicula', '1948', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/jspzrrGmGRBr8u4l5Wc3WiDpOUz.jpg', NULL),
(247, 89482, 'Guerreros', 'pelicula', '2002', 'Kosovo, invierno de 1999. Las fuerzas de la KFOR desempeñan su tarea humanitaria al tiempo que tratan de mantener una difícil neutralidad entre los albanokosovares y los serbios. Un pelotón de ingenieros del Ejército español se ve involuntariamente envuelto en la espiral de violencia que provocan los dos bandos.', '??', 'es', 'https://image.tmdb.org/t/p/w500/kQW4BMqtC399j5OCZ3f9rVxiDUW.jpg', NULL),
(248, 596298, 'Monstruo Dios', 'pelicula', '2019', 'Una noche de bruma, las vacas huyen, una niña es elegida y una adolescente intenta recuperar su libertad. Dios es ahora una central eléctrica.', '??', 'es', 'https://image.tmdb.org/t/p/w500/1D4hn49jzH43ziwdDMAdWnm6q3M.jpg', NULL),
(249, 1425633, 'Leticia', 'pelicula', '2005', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/nimGkX470vWKNKb1zPJCAk1kZqk.jpg', NULL),
(250, 163422, 'Tata Mía', 'pelicula', '1986', 'Elvira, hija de un militar caído en desgracia, que ingresó en un convento siendo muy joven, lo abandona y regresa a su casa de Madrid para instalarse con su querida tata, buscando una ayuda para superar su crisis. Sin embargo el país ha cambiado tanto en sus años de enclaustramiento que poco o nada tiene que ver con sus recuerdos de infancia...', '??', 'es', 'https://image.tmdb.org/t/p/w500/zRqKT8aDmwPzlwWeMhyMzFUn6Et.jpg', NULL),
(251, 541972, 'Barrio Salvaje', 'pelicula', '1985', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/jcGFDIjKX6VdgC8DMCIuk7HG7qU.jpg', NULL),
(252, 147589, 'Garringo', 'pelicula', '1969', 'Cuando Johny era pequeño, vio cómo un oficial del ejército mataba a su padre, que era un desertor. A continuación huyó y fue acogido por un granjero que lo trató como a un hijo. Pasaron los años, y Johny se convierte en un pistolero que se dedica a matar soldados. Hasta que el ejército decide mandar tras él al violento teniente Garrringo. Ahora, su padre adoptivo es el sheriff del pueblo. (FILMAFFINITY)', '??', 'es', 'https://image.tmdb.org/t/p/w500/49kQgSj5Y0yw5jZ3IjKOKzaDnfv.jpg', NULL),
(253, 1028724, 'Toros', 'pelicula', '1995', '', '??', 'es', NULL, NULL),
(254, 918421, 'Verde pistacho', 'pelicula', '2016', 'Llegó la Navidad, y con ella los problemas con el pequeño Tomás, quien ha perturbado la paz del vecino de enfrente arrojándole todo tipo de objetos. Las reprimendas de los padres darán pie a una visita inesperada…', '??', 'es', 'https://image.tmdb.org/t/p/w500/e7CnUl5G5q1moGyxSdgz10Z7GyF.jpg', NULL),
(255, 618400, 'Hechos consumados', 'pelicula', '1986', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/uoci8sQJWtqLJIYZKE4SH6CO2uC.jpg', NULL),
(256, 56647, 'Primos', 'pelicula', '2011', 'A Diego (Quim Gutiérrez) lo ha dejado su novia Yolanda (Nuria Gago) cinco días antes de la boda. ¿Qué es lo más maduro y sensato que debe hacer para superarlo? 1.- Presentarse en la iglesia el día de la boda por si ella se arrepiente. 2.- Emborracharse y despotricar junto a sus primos Julián (Raúl Arévalo) y José Miguel (Adrián Lastra). 3.- Ir con sus primos a las fiestas de Comillas, el pueblo donde veraneaban de pequeños, y allí intentar recuperar a Martina (Inma Cuesta), el amor de su adolescencia.', '??', 'es', 'https://image.tmdb.org/t/p/w500/mPZj6Uym4xCxADxkuWSKKEV5azf.jpg', NULL),
(257, 283252, 'Dollar Mambo', 'pelicula', '1995', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/qJ4hrmTotIzqwjUa0Qr0MhPg3rK.jpg', NULL),
(258, 764777, 'Malditos', 'pelicula', '2020', 'Malditos explora el espectáculo radical de teatro/competición “Danzad Malditos”, en el que ficción y realidad colapsan dentro y fuera del escenario, mientras las nociones de éxito y fracaso acaban por condicionar los sueños personales y colectivos de los protagonistas.', '??', 'es', 'https://image.tmdb.org/t/p/w500/b0ab5XMumI3etdudxpPqq0QBdiJ.jpg', NULL),
(259, 127430, 'Pubis angelical', 'pelicula', '1982', 'Trata sobre tres mujeres, tres historias, o quizás una sola historia en distintas proyecciones de tiempo y espacio. El Ama desea desentrañar el significado de ser mujer y es la víctima de Hollywood. Ana es el producto de una sociedad regida o dominada por los hombres.', '??', 'es', 'https://image.tmdb.org/t/p/w500/ArXoaNAYENG2p9t6P2q3QcLdPyF.jpg', NULL),
(260, 936386, 'El agua', 'pelicula', '2022', 'Ana, su madre y su abuela viven en un pequeño pueblo del sureste de España donde las tres son miradas con recelo.', 'FR', 'es', 'https://image.tmdb.org/t/p/w500/kUdDRXx1EaJ299Zl2kTkVJGOhm0.jpg', NULL),
(261, 41782, 'Amantes', 'pelicula', '1991', 'Navidades de 1953. Paco termina el servicio militar y antes de regresar a su pueblo decide quedarse en Madrid y reunir el dinero necesario para casarse con su novia Trini. Así, se aloja en casa de Luisa, una misteriosa viuda con la que pronto empieza una apasionada relación. Paco cada vez se siente más atrapado en las redes de Luisa, así que tendrá que buscar una solución, por muy trágica que sea.', '??', 'es', 'https://image.tmdb.org/t/p/w500/udBbB8KGAC661nTkjxqPx1MKNSH.jpg', NULL),
(262, 559763, 'Soleils noirs', 'pelicula', '2019', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/18FZx7ALJ2fsa2DfhqDDAAf5MMh.jpg', NULL),
(263, 35942, 'Cámara oscura', 'pelicula', '2003', 'Un grupo de jóvenes coincide en Costa de Marfil, inscritos en la misma expedición de submarinismo. Al llegar al lugar donde tienen que hacer sus prácticas de submarinismo, encuentran flotando el cadáver de un hombre con signos visibles de tortura. La situación se complica cuando debido a un accidente quedan aislados en mitad del océano. Su salvación se vislumbra cuando ven aparecer un viejo mercante', '??', 'es', 'https://image.tmdb.org/t/p/w500/ovZ6TJFILGe1mC2TFFpn8PG96oQ.jpg', NULL),
(264, 676022, 'Los chacales', 'pelicula', '1963', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/qm96GSKToeI2eqAZzexlJgppY5z.jpg', NULL),
(265, 1018986, 'lumbrensueño', 'pelicula', '2023', 'Lucas es un chico sin rumbo que trabaja haciendo hamburguesas y que pasa las tardes perdiendo el tiempo con Oscar, su amigo ‘otaku’ y compañero de trabajo, quien le da a guardar una misteriosa caja antes de emprender un lejano viaje. El olvidado tesoro de su amigo revelará el camino que siguió y provocará que Lucas encuentre una manera renovada de mirar el mundo.', '??', 'es', 'https://image.tmdb.org/t/p/w500/fLyMXmELCaf0HILz0P6yhL0TGgi.jpg', NULL),
(266, 841229, 'Hasta encontrarte', 'pelicula', '2013', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/jWg477fLpLpmS1pp8NLDFupfooK.jpg', NULL),
(267, 86440, 'Voy a explotar', 'pelicula', '2008', 'La joven Maru conoce a Román, un adolescente con fantasías violentas. En una rebelión contra todo, ambos deciden huir a un lugar donde nadie los encuentre. La insospechada nueva intimidad los lleva a descubrir su sexualidad y una intensa vida en pareja, que los une y a la vez los confunde. A pesar de saberse buscados por sus padres, los jóvenes buscan expandir los límites de su recién formado paraíso y salen al mundo real, donde las heridas son verdaderas y las acciones tienen consecuencias. (FILMAFFINITY)', '??', 'es', 'https://image.tmdb.org/t/p/w500/4EC76HVoUI2pPSEv54OHV7UIu6c.jpg', NULL),
(268, 326853, 'Hermelinda Linda', 'pelicula', '1984', 'La historia se desarrolla durante un congreso de brujas durante el Día de Muertos, en el que Hermelinda les cuenta a las demás brujas acerca de su enfrentamiento con un delegado municipal corrupto que tiene la intención de acabar con \"Bondojia', '??', 'es', 'https://image.tmdb.org/t/p/w500/eQbQK2TjmiNkrWB92bTpYU5ueq1.jpg', NULL),
(269, 768325, 'Frutilla', 'pelicula', '1980', 'Una muchacha llega a Buenos Aires desde Catamarca y cumple su sueño de ser actriz.', '??', 'es', 'https://image.tmdb.org/t/p/w500/tQIsulVpAmLJX7ruloX0Ozi4l4a.jpg', NULL),
(270, 768172, 'Don Juan Tenorio', 'pelicula', '1949', 'Drama romántico que transcurre en la Sevilla de 1545, en los últimos años del rey Carlos I de España.', '??', 'es', 'https://image.tmdb.org/t/p/w500/3BbJIoIGV2l5xeLYORolXA0QAD5.jpg', NULL),
(271, 127864, 'Blancanieves', 'pelicula', '2012', 'Sevilla. Años veinte. Carmen (Macarena García, \'Amar en tiempos revueltos\'), ha vivido toda su infancia bajo el yugo de su terrible madrastra, Encarna (Maribel Verdú, \'La buena estrella\'). Cansada de la represión a la que la somete, la joven decide escapar y vivir nuevas aventuras que le permitan olvidar su traumático pasado. Carmen iniciará un viaje de huída y de descubrimientos que la transformará por completo. Durante ese viaje, contará con una compañía muy especial: la de siete \"enanitos toreros\", que intentarán protegerla en todo momento.  El director Pablo Berger nos introduce en el territorio de lo grotesco y lo fantástico a través de esta fábula basada en el famoso cuento de los hermanos Grimm, que utiliza los elementos de la España castiza de la época para crear una atmósfera tan original como la propia concepción del film: en blanco y negro y sin diálogos. Una vuelta a los orígenes de cine a través de unas imágenes poderosas acompañadas de una partitura original.', '??', 'es', 'https://image.tmdb.org/t/p/w500/64vBklpYgksumhSwrJdTvHeySfS.jpg', NULL),
(272, 430013, '22 ángeles', 'pelicula', '2016', 'Historia basada en hechos reales sobre la expedición encabezada por el doctor Francisco Javier Balmis, que llevó la vacuna de la viruela a las Américas a principios del siglo XIX.', '??', 'es', 'https://image.tmdb.org/t/p/w500/68g4XH8EJh7OJ4GZGSXGW3tBXIl.jpg', NULL),
(273, 239109, 'Volantín cortao', 'pelicula', '2013', 'Paulina, de 21 años, es una trabajadora social en prácticas que realiza su pasantía en un centro de reinserción juvenil. Allí conoce a Manuel, de 16 años, con quien comienza una amistad que la llevó a cuestionar su vocación y a lanzarse a una segunda adolescencia, esta vez libre de la tiranía de la convención y la rutina, robando horas de un mundo que no le pertenece: Las calles de Santiago.', '??', 'es', 'https://image.tmdb.org/t/p/w500/6s3kljVGgkC0jI3YaMCt6iSHC0x.jpg', NULL),
(274, 232402, 'Tupac Amaru', 'pelicula', '1984', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/xZMCpR56y47oPeFRfITceJ647cn.jpg', NULL),
(275, 1137857, 'Reflejo', 'pelicula', '2023', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/p7kUGbGiwt7sCcz6suglTjcg9pm.jpg', NULL),
(276, 341242, 'Sonámbulos', 'pelicula', '1978', 'La acción trascurre durante el proceso de Burgos. Ana, que trabaja en el Comité por la liberación de unos presuntos terroristas, condenados a muerte, sufre un desmayo. Su tío Norman, antiguo médico a quien retiraron la licencia por contrabando de medicamentos, le ofrece un remedio que puede ayudar a su enfermedad cerebral, pero le advierte que puede tener consecuencias: produce tal desinhibición que el paciente se sitúa más allá del mal y del bien, de la ética y de las convicciones. (FILMAFFINITY)', '??', 'es', 'https://image.tmdb.org/t/p/w500/taO9dl1SpK3hQhQHvbZiGmzdmbr.jpg', NULL),
(277, 106873, 'Polvo enamorado', 'pelicula', '2003', 'Cuando tenía 17 años, Natalia se casó con Don Matías siguiendo los deseos de sus padres. Pero no fue hasta que el Padre Santiago llegó a este pequeño pueblo que Natalia se enamoró por primera vez.', '??', 'es', 'https://image.tmdb.org/t/p/w500/nHbVUuiDO5Dn8FBudee5QlkpHEq.jpg', NULL),
(278, 602415, 'Calé', 'pelicula', '1987', 'Cristina, madura actriz teatral, va a encarnar a Eliza en una versión de Pigmalión. La gitana Estrella le ayuda a comprender el mundo calé y entre ambas mujeres estalla una pasión incontrolable.', '??', 'es', 'https://image.tmdb.org/t/p/w500/ay8kjKLOtoSojLs6vvrjqbSJCM8.jpg', NULL),
(279, 815643, 'El heredero', 'pelicula', '1999', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/jDImZ4uuPZLFnDDnkGoY8iu7ghE.jpg', NULL),
(280, 585172, 'Perro bomba', 'pelicula', '2019', 'Un joven inmigrante haitiano afincado en Santiago de Chile, verá sacudido el equilibrio de su vida tras una serie de acontecimientos inesperados que alimentarán unas profundas reacciones racistas en su entorno.', '??', 'es', 'https://image.tmdb.org/t/p/w500/2Du3VfvKSvVEgzSin6Dd4TxosQD.jpg', NULL),
(281, 96287, 'Déficit', 'pelicula', '2007', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/zCIESQoUv7tO49Jk5qRimDAjl32.jpg', NULL),
(282, 1108333, 'Fauna', 'pelicula', '2023', 'En un bosque de las afueras de Barcelona, un viejo pastor enfermo y su rebaño de ovejas viven cerca de un laboratorio de alta tecnología dedicado a la investigación sanitaria y a la experimentación con animales.', '??', 'es', 'https://image.tmdb.org/t/p/w500/efwxg648iEtHq0C8FOIYeEJRX7F.jpg', NULL),
(283, 670891, 'Zorina', 'pelicula', '1949', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/ma17oRK5i4M8PGPZBQDCNVlyGWc.jpg', NULL),
(284, 556069, 'Playa prohibida', 'pelicula', '1956', 'Tras encontrar el cadáver de un hombre en la playa, una hermosa mujer (Rossana Podestà) huye de los policías que investigan el caso. Resolver la enigma policíaca resultará más difícil que previsto. Un joven cineasta de vacaciones en la región decidirá hacer por sí mismo su propia investigación. Habrá asuntos de rivalidad entre primos amorosos de la misma mujer y por cosas de herencia.', '??', 'es', 'https://image.tmdb.org/t/p/w500/cA07wnaZpJJnSTqF2Q2T8bdcEt5.jpg', NULL),
(285, 674062, 'Cien muchachas', 'pelicula', '1957', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/vIBv1NeMBBHOJY4Oxa3tdgTHiM.jpg', NULL),
(286, 550778, 'Sirenas', 'pelicula', '1995', 'El abuelo Antonio se libró de morir ahogado en el naufragio de su barco cuando navegaba. Le salvó su sordera, ya que no oyó el canto de las sirenas que le llamaban desde el fondo del mar. Pero las sirenas siguen existiendo en aguas saladas; lo que de ellas se desprende llega a la ciudad y antes o después todos acabamos escuchándolas.', '??', 'es', 'https://image.tmdb.org/t/p/w500/fitzvuZpj3ZxGt6sIfEyhMOONcL.jpg', NULL),
(287, 1315988, 'Mikaela', 'pelicula', '2025', 'Víspera de Reyes. Una tormenta de nieve sin precedentes asola España. En medio del caos de una autopista colapsada, un grupo de atracadores aprovecha la oportunidad para asaltar un furgón blindado. A escasos metros se encuentra Leo (Antonio Resines), un policía en las últimas que no tiene nada que perder. Con la ayuda inesperada de una joven, juntos tratarán de evitar que la banda huya con el botín en una persecución a contrarreloj en medio del temporal.', 'ES', 'es', 'https://image.tmdb.org/t/p/w500/wnTNpOoqjqOLj2oIoGE9MnPFa4o.jpg', NULL),
(288, 575977, 'I Am an Artist', 'pelicula', NULL, '', '??', 'es', 'https://image.tmdb.org/t/p/w500/eG9wzgWiGcEDYpb2KZzhtrafYaX.jpg', NULL),
(289, 300906, 'Atroz', 'pelicula', '2018', 'Atroz es una película que retrata la historia de 2 asesinos seriales a quienes les son confiscadas unas cintas de video, tras ser detenidos por causar un accidente de tránsito. Tales cintas contienen asesinatos brutales que muestran la maldad humana, así como los antecedentes, parafilias y la psique de estos asesinos. Largometraje basado en el cortometraje del mismo título de 2012.', '??', 'es', 'https://image.tmdb.org/t/p/w500/6Izf4JuMgP5xi0EbB4gCLWDcHIH.jpg', NULL),
(290, 1082170, 'Político incorrecto', 'pelicula', '2013', 'El carismático alcalde de un pequeño pueblo empieza a ser políticamente incorrecto en twitter.', 'ES', 'es', 'https://image.tmdb.org/t/p/w500/c5mXO3ZMMM1tKnUbwACBzNlJdp9.jpg', NULL),
(291, 537869, 'Familia sumergida', 'pelicula', '2018', 'El mundo de Marcela se vuelve extraño y desconocido después de que su hermana Rina muere. Se siente perdida en su propia casa, y su relación con su esposo e hijos parece sufrir. Pero cuando Nacho, una joven amiga de su hija, cae inesperadamente, comienza a hablar y caminar con él. Poco a poco Marcela comienza a tener conversaciones con familiares de otra dimensión.', '??', 'es', 'https://image.tmdb.org/t/p/w500/qKrpynyBiP9NKLywKLltchoIpT5.jpg', NULL),
(292, 1130428, 'Pájaros', 'pelicula', '2024', 'Es la historia de un viaje, el de dos hombres que, pasados ya los 50, van en busca de una grulla inalcanzable y un futuro imposible. Un viaje en el que recorrerán Europa, pero también su propia vida, sus relaciones, la familia, el amor, el sexo… como una catarsis ante el inevitable paso del tiempo.', '??', 'es', 'https://image.tmdb.org/t/p/w500/2dzbKNXxSt9ai8cjVOem81pj1fA.jpg', NULL),
(293, 671745, 'Sucesos distantes', 'pelicula', '1996', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/ksoqo4omCz9oteDZzjP62X5buP4.jpg', NULL),
(294, 143311, 'Luna Escondida', 'pelicula', '2012', 'Después de que una misteriosa y bella mujer latina llamada Miranda hace una aparición dramática en el funeral de un hombre, sorprendiendo a su familia acomodada del sur de California, Victor, el hijo de este hombre, se dirige a México para averiguar la verdad sobre la relación que tenia con su padre muerto.  Encuentra a Miranda en la ciudad de Guanajuato viviendo con otro hombre, Tobías. Cuando Victor se enfrenta a Miranda, ella niega haber conocido a su padre y dice que nunca más volverán a saber de ella. Si Miranda está diciendo la verdad, ¿qué estaba haciendo exactamente en el funeral del padre de Victor? ¿Quién es el hombre con el que está viviendo ahora? Su confrontación es el comienzo de una cadena de eventos donde los protagonistas deberán resolver el dilema que ocurre cuando el amor verdadero llega dos veces al mismo tiempo.', '??', 'es', 'https://image.tmdb.org/t/p/w500/6nFlug81zbUSLyld3u5mvlUeIlf.jpg', NULL),
(295, 763563, 'Unboxing Ibai', 'pelicula', '2020', 'Cosas extrañas empiezan a pasar durante el unboxing de la PlayStation 5 del famoso streamer Ibai Llanos.', '??', 'es', 'https://image.tmdb.org/t/p/w500/ebiGDHDePiX7Vgrfc5xlfPGlkFy.jpg', NULL),
(296, 397987, 'Eulalia', 'pelicula', '1987', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/l3xW3dMt1RHCoR0G9RqcNBxyXgc.jpg', NULL),
(297, 514612, 'Camino sinuoso', 'pelicula', '2018', 'Mía Siero, una ex atleta olímpica es expulsada de una competición internacional por consumo de drogas no permitidas. Años después, y como consecuencia de esas sustancias en su cuerpo, sabrá que no puede tener hijos de forma natural. Esta noticia golpeará emocionalmente a Mía, al tiempo que se entera de que su padre está muriendo y deberá viajar a su ciudad natal para ordenar los trámites de herencia.', '??', 'es', 'https://image.tmdb.org/t/p/w500/sRZRKTYiWPGHXxNCHoTXLf59ELb.jpg', NULL),
(298, 655181, 'Libertad', 'pelicula', '2021', 'Después de mucho tiempo sin coincidir en su casa de verano, la familia Vidal pasa las últimas vacaciones con la abuela Ángela, que sufre Alzheimer avanzado. Por primera vez en su vida, Nora (14), siente que no encuentra su lugar: los juegos de niños le parecen ridículos y las conversaciones de los adultos todavía le van grandes. Pero todo cambia con la llegada de Libertad (15), la hija de Rosana, la mujer colombiana que cuida a Ángela.', '??', 'es', 'https://image.tmdb.org/t/p/w500/fHIvnHO8S1kCWpQ9UDO6U6UgZP7.jpg', NULL),
(299, 841169, 'Dos plebes', 'pelicula', '2000', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/oMNXbkBZ5eXN3ylMqODJbJWOvK6.jpg', NULL),
(300, 726208, 'Voces', 'pelicula', '2020', 'Daniel (Rodolfo Sancho) y Sara (Belén Fabra) son un matrimonio con un hijo de 9 años, Eric (Lucas Blas), que acaban de trasladarse a un nuevo hogar. Sin embargo, no saben que esa propiedad es conocida en el vecindario como \"la casa de las voces\". Eric es el primero en percatarse de los extraños sonidos que se ocultan tras cada puerta y que intentan comunicarse con la familia. Pese a que al principio Daniel y Sara creen que se trata de un producto de la imaginación de su hijo, poco a poco comienzan a percibir también esos sucesos paranormales, convirtiéndolos en una realidad.  Este largometraje de terror, que trata el poder sugestivo de las psicofonías, está dirigida por Ángel Gómez.', '??', 'es', 'https://image.tmdb.org/t/p/w500/kB1jM3vsbkWBxLo4esCDvgrsZVj.jpg', NULL),
(301, 405554, 'Mariona Rebull', 'pelicula', '1947', 'Barcelona, España, a finales del siglo XIX. Joaquín Rius, un prominente hombre de negocios, se casa con la joven Mariona Rebull. Su aparente felicidad se ve ensombrecida por la llegada de Ernesto Villar, amigo de Joaquín y antiguo amante de Mariona.', '??', 'es', 'https://image.tmdb.org/t/p/w500/lqLQQqEp1qJAfAogZBdZvIDhODk.jpg', NULL),
(302, 20511, 'Crónicas', 'pelicula', '2004', 'El ambicioso periodista Manolo Bonilla (Leguizamo) tiene un programa dirigido a la población hispana de Miami. Buscando una buena historia, viaja a un pueblo de Ecuador para investigar a un asesino en serie de niños conocido como \"El monstruo de Babahoyo\". Producida por los directores Alfonso Cuarón y Guillermo del Toro, con música de Antonio Pinto (Ciudade Deus) y con un reparto de primer nivel, Sebastián Cordero firma un thriller sobre la ética del periodismo. Presentada con éxito en los festivales de Cannes, Toronto y Sundance, fue además candidata a los Oscar por Ecuador a la mejor película de habla no inglesa. (FILMAFFINITY)', '??', 'es', 'https://image.tmdb.org/t/p/w500/pPQOC8eyaJmlouI9Il4dCF2iS6E.jpg', NULL),
(303, 63557, 'Ligeramente viudas', 'pelicula', '1975', 'Leonor y Engracia, dos mujeres jóvenes, enviudan por el accidente de sus respectivos esposos, y pronto buscarán recambio sin demasiado recato. Cuando conozcan a José Luis y Eugenio todos los planes hechos cambiarán con la intención de llegar al altar.', '??', 'es', 'https://image.tmdb.org/t/p/w500/rYBol4MMvQt3dsx73lMEhUlfaJ8.jpg', NULL),
(304, 422297, 'Deseo', 'pelicula', '1976', 'Una profesora particular es contratada por los padres de un adolescente para que éste apruebe los cursos. Conforme avanzan las clases, la profesora siente cada vez más la atracción que ejerce sobre el muchacho.', '??', 'es', 'https://image.tmdb.org/t/p/w500/cSBrVTNi2dNC6vHS3PSTFdGXKzb.jpg', NULL),
(305, 1132068, 'Pole Dance', 'pelicula', '2023', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/2kdVapuIprmgpLJKRs4ZjlFQVQj.jpg', NULL),
(306, 388406, 'Campeones', 'pelicula', '2018', 'El 2 de octubre del dos mil cinco, en la ciudad de Lima, Perú, un entrenador y veintiún futbolistas hicieron historia ganando la primera Copa Mundial Sub-17 de México. Sin embargo, nuestra historia no comienza en esa fecha; comenzó mucho tiempo atrás y se va a los campos de fútbol lejanos. \"Champs\" cuenta la historia en retrospectiva, de todos los altibajos, las luchas, los eventos divertidos e incluso tristes junto con la intensa preparación que enfrentaron para lograr sus objetivos. Viajamos en una aventura personal con el entrenador y los miembros de su equipo, viviendo el drama personal de los jugadores y sus antecedentes familiares, los esfuerzos diarios que tuvieron que enfrentar para alcanzar la excelencia requerida para lograr el éxito deseado. \"Champs\" no es una película sobre fútbol; es una película sobre campeones.', '??', 'es', 'https://image.tmdb.org/t/p/w500/oJ4ekOowerAJwVZFBuiv5XebcbD.jpg', NULL),
(307, 1397372, 'Motel Tlalpan', 'pelicula', '2024', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/c3UWELJxgalitM1mDlQ2lU7Mo2T.jpg', NULL),
(308, 365798, 'Las interesadas', 'pelicula', '1952', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/5UbmUaGEb9GziufiW2d6kitnP5G.jpg', NULL),
(309, 289972, 'Blanca Madison', 'pelicula', '1998', 'Urbano, que acaba de salir de la cárcel, recoge en su taxi a unas prostitutas con destino a un club al otro lado de la frontera. En el taxi va también una chica. En la misma dirección viaja Blanca Madison, cantante de boleros. Blanca regresa a la ciudad en la que siendo niña sufrió vejaciones a manos del propietario de un club nocturno, llamado Xesús Bocanegra. Entre actuación y actuación organiza, con desesperada frialdad matemática, una venganza: Matar a Bocanegra. (FILMAFFINITY)', '??', 'es', NULL, NULL),
(310, 427126, 'IKEA2', 'pelicula', '2016', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/wAB1lbSq7A0ii1BfZS9T7IgRzgT.jpg', NULL),
(311, 194158, 'Sensualidad', 'pelicula', '1951', 'El severo juez Alejandro Luque se ve tentado por la sensualidad encarnada en Aurora Ruiz, una prostituta que él condenó a prisión y que ha logrado obsesionarlo. Cegado por la pasión, Luque cometerá una serie de delitos con tal conquistar a la cruel cortesana, sin importarle sacrificar toda una vida de rectitud.', '??', 'es', 'https://image.tmdb.org/t/p/w500/hWhWhJbgpO0kgc2PB9pbPcsLePz.jpg', NULL),
(312, 415979, 'Verde', 'pelicula', '2016', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/sfENheEv4rr6fXlUVyLrDuFbAPs.jpg', NULL),
(313, 421990, 'Paraíso', 'pelicula', '1970', 'Los problemas surgen entre los buzos Román y Lauro cuando el primero se enamora de una prostituta en las playas de Acapulco.', '??', 'es', 'https://image.tmdb.org/t/p/w500/gcQxlrB9kcgPFa4XXywAB9b8B6u.jpg', NULL),
(314, 111720, 'Habanera', 'pelicula', '1958', 'Año 1860. Rosa María, hija de un acaudalado hacendado cubano, está estudiando en un colegio de monjas en Cádiz y solicita regresar a Cuba después de estar varios años en España. Pero resulta que la situación económica de su padre es desastrosa y por esta razón intenta retrasar el regreso de su hija, ocultándoselo. Rosa María no entiende nada y ante la negativa de su padre se fuga del colegio, embarcando de polizón en un navío rumbo a su patria.', '??', 'es', 'https://image.tmdb.org/t/p/w500/7An9CJmo8UTjShbtZm6VK97o6ix.jpg', NULL),
(315, 11148, 'XXY', 'pelicula', '2007', 'Alex (Inés Efron) es una singular adolescente de quince años que esconde un secreto: es hermafrodita. Poco después de su nacimiento, sus padres, Kraken (Ricardo Darín) y Suli (Valeria Bertuccelli), decidieron dejar Buenos Aires para vivir, aislados del mundo, en una cabaña de madera a orillas del mar. Lo que pretendían era que Alex creciera libre de cualquier tipo de prejuicios, protegida y feliz, hasta que llegara el momento de decidir juntos qué camino seguir...', '??', 'es', 'https://image.tmdb.org/t/p/w500/wREgo3KR1wW6s0MxhsJO7AnKVOj.jpg', NULL),
(316, 176707, 'Una rosa de Francia', 'pelicula', '2006', 'En Cuba, Simón (Perugorría), un criminal muy seductor, traslada en su viejo barco emigrantes clandestinos a Nueva York y después los abandona a su suerte en un islote. En una ocasión, una patrullera norteamericana descubre el barco e inicia su persecución hasta penetrar en aguas territoriales cubanas. Andrés (Álex González), un joven marinero, le salva la vida a Simón, pero resulta herido. Simón le estará siempre agradecido, a pesar de que Andrés se enamora de Marie (Ana de Armas), una adolescente que está bajo su protección. El conflicto está servido. Marie y Andrés intentarán huir de Cuba a Nueva York, pero Simón hará todo lo posible para impedirlo.', '??', 'es', 'https://image.tmdb.org/t/p/w500/tMGZp0VDTy4e27gBDLfsiRgZ4gY.jpg', NULL),
(317, 648532, 'Socarrat', 'pelicula', '2009', '133/5000\r Todos tenemos secretos. Todos tenemos familia. Todos buscamos la felicidad. ¿Qué pasa si compartimos nuestros secretos y buscamos la felicidad juntos?', '??', 'es', 'https://image.tmdb.org/t/p/w500/tjovVqJtj7vPpevee0av5UOVXis.jpg', NULL),
(318, 1534690, 'Teléfono público', 'pelicula', '2025', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/kOwZDAGAwDF7PYkbDci1Zti5ebE.jpg', NULL),
(319, 670939, 'Desde dentro', 'pelicula', '2023', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/Ajy2G7B9OdkKeZUwxmWVtPBAj48.jpg', NULL),
(320, 123103, 'Aftershock', 'pelicula', '2012', 'Un joven apodado Gringo (Roth) está pasando unas vacaciones de lujo en Chile, pese a que no ha conseguido ligar con ninguna chica. Cuando él y sus amigos logren al fin que unas mozas los acompañen en el viaje, un terremoto convertirá las idílicas vacaciones en una auténtica pesadilla.', 'CL', 'es', 'https://image.tmdb.org/t/p/w500/jbPqPMbJbhFttJy2joNVsO7a7Po.jpg', NULL),
(321, 594692, 'Madre', 'pelicula', '2019', 'Elena perdió a su hijo Iván, de seis años, en una playa de Francia. Ahora Elena vive en esa playa y está empezando a salir de ese oscuro túnel donde ha permanecido anclada todo este tiempo.', '??', 'es', 'https://image.tmdb.org/t/p/w500/eO5rhMM2SftbAUWDGclVuaBVL5W.jpg', NULL),
(322, 128237, 'Viola', 'pelicula', '2012', 'Cecilia ocupa sus días ensayando la comedia Noche de reyes de W. Shakespeare mientras Viola deja pasar los suyos arriba de una bicicleta repartiendo películas pirateadas. Entre diferentes teorías del deseo, entre sueños, versos y ficciones en un mundo de mujeres shakesperianas, los misterios no se resuelven, pero el amor circula irrefrenablemente.', '??', 'es', 'https://image.tmdb.org/t/p/w500/x1FV519m6HfN2uMPpHiIQnYkukl.jpg', NULL),
(323, 512842, 'Misterio', 'pelicula', '1980', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/gPRrVd6GsFBo4etjYq7EtPPlMgU.jpg', NULL),
(324, 20071, 'Pagafantas', 'pelicula', '2009', 'Pagafantas es el pringado pegado a la chica guapa; el que no tiene ninguna posibilidad de ligársela, pero que está acechando por si cae algo. Ella lo ve como amigo y jamás se plantea que el chaval represente \'peligro\' sexual alguno.', '??', 'es', 'https://image.tmdb.org/t/p/w500/6ZmQLbzOkrNfcnqUhmqKWeyDps0.jpg', NULL),
(325, 453185, 'Juan guerrero', 'pelicula', '1963', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/mQPAM1A94rqPiZk55t804CHIvX5.jpg', NULL),
(326, 260803, 'Madrid', 'pelicula', '1987', 'Hans, un realizador alemán, es enviado a Madrid para hacer un documental sobre la capital y la Guerra Civil Española, cuando se cumple el 50 aniversario. Lo acompaña Lucía, su montadora, y Goyo, el operador de cámara. Juntos recorren Madrid grabando imágenes y relacionándolas con el pasado, y tras ello, Hans se da cuenta que la capital es una ciudad mucho más abierta y seductora de lo que pensaba. Entonces, Hans se pregunta sobre el sentido de su trabajo, pero la idea de cambiar el punto de vista del documental no tendrá un buen recibimiento por parte de aquellos que lo han contratado', '??', 'es', 'https://image.tmdb.org/t/p/w500/ud7VaCz7DG6JdLSZtpBKnTMO24h.jpg', NULL),
(327, 865367, 'Cadejo Blanco', 'pelicula', '2023', 'Sarita vive con su hermana Bea en un barrio popular de Ciudad de Guatemala. Una noche, después de una fiesta, Bea desaparece. Convencida de que Andrés, el peligroso ex novio de su hermana, tiene algo que ver, Sarita se convierte en su amiga y se infiltra en su pandilla.', '??', 'es', 'https://image.tmdb.org/t/p/w500/21OYAbJSCsFChLb6MnVI6SMfAwD.jpg', NULL),
(328, 526970, 'Pervertida', 'pelicula', '1946', '', '??', 'es', 'https://image.tmdb.org/t/p/w500/scek25UYJuIOFl905iS3F6Ps5lY.jpg', NULL),
